/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20241007-4","meetingId":"r06-c-settlement","date":"2024年10月7日","dateIso":"2024-10-07","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ５時０６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"おはようあります。すごく久しぶりにトップバッターをやるものですから少々緊張しておりますけれども、２３７ページの障害児者福祉施設運営費、２４３ページ高齢者福祉施設運営費、２６９ページ区立保育園費、それから２７９ページの私立保育園費に関連する形でお伺いしていきたいと考えています。人件費だと思っているけれども、そこをぜひ教えていただきたい。もう一点。これはこういう考え方もある。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"モニタリング等、指定管理施設の財政状況等についてお話をします。こちら、先日の厚生委員会等でご説明をさせていただいてはおりますが、多くの施設において、確かに収支でマイナスが出ているような状況です。障害者分野の指定管理のモニタリングにおきましても、やはり赤字部分の原因につきましては、議員おっしゃられるとおり、まず１つはコロナの影響で利用控えがあること。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"区長もグループホームを１００名分ぐらいと言ったのだけれども、これは民間地ではもう今無理です。当初の補助金はじゃぶじゃぶ出るわけだから、後の運営をどうするかということを考えてあげるということをやっていけば、小規模多機能は少し置いておいてもいいから、それなりにグループホームなどは進んでいくのだと私は思っているので、ぜひそこら辺の感覚を、最後お話しを伺いたいと思う。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"参加された方から、ぜひ自分の土地を活用したいというような意向も伺っているところですので、そういったセミナーなども含めまして、土地の確保に努めてまいりたいと考えています。これが結果的に、入居者が長期にグループホームにいていただくということになって、事業者の支援になるのかなというところで進めているところですが、それ以外の事業者の声にも今後耳を傾けながら。","id":"exchange-002"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私からは、２３５ページの福祉タクシー・自動車燃料費助成について、また同じく２３５ページの日常生活用具給付事業について、それぞれ質疑させていただきたいと思います。昨年の第３回定例会の一般質問の場で訴えさせていただいた内容ですが、今年度からタクシー券と福祉自動車燃料費助成券が併用できることになりまして、当事者の方々からは大変にありがたいと感謝の声をいただいております。","respondent":"松山障害者支援課長","answer":"分冊にした影響で使いにくいといったお声は区には届いておりませんけれども、ただしご利用しやすい取扱いの方法につきましては、今後障害者の方のご意見を聞きながら、タクシー、ガソリンスタンドの会社と調整しつつ検討してまいりたいと考えております。","id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問","question":"福岡市では、障害のある方の社会参加を応援するため、交通費の一部を助成する福祉乗車券等交付の方法として、７つの券種のうちの１種を選択できます。都内でも交通系ＩＣカードを活用できるタクシー事業者は、都内大手タクシー４事業者も含め、さらに増えつつあります。改めて交通系ＩＣカードなどでの交付について、区の見解をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"タクシーとガソリンスタンドが共通で使用できるようなＩＣカードというのが今のところございませんで、今現在としましては難しいところですけれども、今後、ＩＣ化の拡大の動向を注視しながら検討してまいります。さらなる利便性の向上に努めていきたいと考えております。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ぜひ前向きに検討していただければと思います。続いて、重度障害者の家族のいる世帯では、介護タクシーを使用せざるを得ないという現状があります。年間４万２,０００円の福祉タクシー利用券を使っていても、経済的な負担は相当なご負担になります。物価高騰を鑑みて、さらなる助成の増額を要望したいと思いますが、この辺について区の見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"福祉タクシー等の金額についてです。実際、品川区としましては現在４万２,０００円で、他区はそれ以上、またそれ以下のところもあります。今後物価高騰の動向を鑑みながら、障害者の方のお声もありますので、さらに検討を深めていきたいと考えております。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひお願いします。この介護タクシーを利用すると、初乗り料金で２,０００円から３,０００円ぐらいの利用料金、加えて、迎車料金と送迎料金がかかって、３,０００円の初乗り料金に片道で５,０００円程度、６,０００円ぐらいかかるかもしれないのですけれども、そうなると往復で１万２,０００円ぐらいかかります。この辺についてどう対応を考えていらっしゃるのか、区の見解をお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"ただし障害者の方からは、乗車料金の助成のみで、それ以外の助成については品川区は現在行っていないことから、車椅子を使用されている方が必ずかかるような料金については、負担が大きいというお声はいただいております。費用負担につきましては、今後検討してまいります。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"例えば、目黒区では介護タクシー利用補助事業があって、区と協定を結んだタクシー事業者を条件に、初乗り料金に当たる予約料、迎車料、基本介助料の２,２５０円の実費を区が負担しています。福祉タクシー利用券だけではなく、介護タクシーを必要とする重度障害者のご家族の方々の負担軽減についてもさらに前向きに考えていただければと思いますが、改めて区の見解をお聞きできればと思います。","respondent":"松山障害者支援課長","answer":"現在予約料、迎車料、基本介助料等については区としては行っておりませんが、やはり車椅子を使用される方は必ずかかる費用ですので、そのようなお声も多くいただいております。今後検討してまいりたいと考えております。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"意見","question":"私もこの現場からの、福祉タクシー券は本当にありがたいというお声はもう十分に聞いておりますが、介護タクシーを使えない現実というのは本当に切実な問題だと聞いています。そこに対しての、実際その現場の立場に立つことは難しいかもしれないですけれども、そこに寄り添うということはできると思いますので、何とぞ区の前向きな対応をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、２６３ページの奨学金貸付事業、２４５ページの福祉人材確保・定着事業、２４９ページの高齢者向けパソコン・スマホ教室、２５５ページの子育て支援情報発信アプリ運用について伺います。奨学金貸付制度について伺います。大学応援資金の利用者は２３人と記載されていますが、主な使用用途は何でしょうか。","respondent":"飛田子育て応援課長","answer":"主な使用用途ですが、学習関連で塾の費用が一番多くなっております。次に、学校への施設整備費や修学旅行の積立金となっております。","id":"exchange-009"},{"speaker":"山本委員","kind":"質問","question":"理解をいたしました。９月１１日号の広報に、品川区奨学金募集の記事が掲載されていましたが、その中に返還免除を目指そうと書かれていました。申請時に立てた具体的な目標の達成により、免除となる仕組みとのことですが、昨年度は何人の方が免除になったのでしょうか。免除にならなかった人数を教えてください。","respondent":"飛田子育て応援課長","answer":"この春高校を卒業しまして、免除申請があった方の人数ですが、１６名でした。申請のあった方は書類選考や面接を行い、品川区奨学金運営委員会に諮り、１６人全員が返還免除となりましたので、免除にならなかった方はいらっしゃいません。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"全員が返還免除となったのですね。すばらしいですね。区内奨学金制度の充実や拡充を図り、奨学生の応援を引き続きお願いいたします。次に、介護人材確保定着事業について伺います。品川介護福祉専門学校の入学者の定員と４月の入学者、それから品川区における介護従事者の全体数を把握するため、本年度開始した区独自の介護職向け居住支援手当の対象者数についてお教えください。","respondent":"菅野高齢者福祉課長","answer":"区独自の介護職員向け居住支援手当につきましては、今回手当を支給するにあたって、改めて各事業所に調査をしましたところ、約６,０００人の方が区内には勤めているということが分かりました。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"一方で、区内介護従事者は６,０００人規模であり、学校の定員では１％にも満たない状況です。令和５年度の補助金を利用した法人の利用実績を確認しますと、品川区では２つの法人だけでした。申請に対する相談の受付とともに、実務的なサポートも併せて要望いたします。都の制度で対象から外れる事業者がある場合には、区独自の制度で支援をすることの検討を要望します。それぞれ区のご見解を伺います。","respondent":"菅野高齢者福祉課長","answer":"東京都が実施している介護職員奨学金返済育成支援事業に関するご質問についてお答えをします。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"福祉人材確保の中で、外国人介護職員確保のための住居支援について伺います。主要成果報告書では、ファミーユ西品川の外国人職員の入居者数が、令和４年の１２名から令和５年は９名に減少していました。事務事業評価シートでは、外国人介護職員確保のための家賃助成が、令和４年の２０件から令和５年には１６件に減少していました。","respondent":"菅野高齢者福祉課長","answer":"こちらのご質問の外国人介護職員確保のための家賃助成につきましては、ファミーユ西品川を活用した外国人介護職員の居住支援確保ということで、こちらシェアハウスとなっておりまして、１戸２人入居で現在６戸、１２人分を貸出しをしています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"さらに今後、日本国内で外国人介護職員の取り合いになるので、他自治体に先行し労働できる環境整備を進めていくべきであるとのご要望を伺いました。私も同じように考えます。外国人介護職員の住居支援の拡大と、労働従事者と家族の生活環境の支援の充実を要望し、次の質問に参ります。次に、高齢者向けパソコン・スマホ教室に関連して、はじめてのスマホ体験教室よろず相談について伺います。","respondent":"樫村高齢者地域支援課長","answer":"令和５年度の実績ですけれども、はじめてのスマホ教室が１２８回実施しまして、２３８名の方にご参加いただきました。スマホよろず相談につきましては１６０回実施して、１,０６５名の方にご参加をいただいたところです。","id":"exchange-014"},{"speaker":"山本委員","kind":"提案","question":"ご要望に応えていただいた会場の増設、そして新しい講座での工夫もよいと考えます。一方、昨年の決算特別委員会の質問でご説明した試算では、対象者が９,０００人いて、今の年間３００人ペースだと３０年かかるというので、大幅なペースアップの要望をいたしました。区が作成したアプリの普及をスマホ教室で積極的に推進することを要望いたします。私の質問は以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"２３１ページ精神障害者地域生活支援センター運営費について、２３７ページ障害者福祉手当等支給事務について伺います。精神障害者地域生活支援センター、西五反田にある「たいむ」のことですけれども、こちらは相談とともに交流や活動の場の提供も行っているということで、大切な役割を担っていると思います。その果たしている役割をどう評価しているのか、その意義について区の認識を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"たいむにつきましては、まずは相談、そして居場所ということで、相談を受けながら、そちらから居場所につなげていくというような、そしてサービスにつなげていくというような、大変重要な入り口の役割を持っていると考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。今、精神疾患に苦しむ方は増えていると思います。そうした方々の中には、病状によってはなかなか電車に乗れないという方もいらっしゃいます。家族会のほうからは、区内にこちら一か所のみの地域生活支援センターということで、増設を求める声が届いております。この施設の増設を検討して具体化すべきだと思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"名前としては地域生活支援センターという、精神障害者に特化したものということではないですが、全ての障害の方にご利用いただける地域活動支援センターとなっており、たいむと同じ役割や機能を担っていると、区としては２か所あるという認識があります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ荏原地域のほうの増設もお願いしたいのですが、検討するべきだと思うのですけれども、いかがでしょうかという質問をします。それと、ほかの障害者の方との兼ね合い。財源確保などを理由に研究課題としておりますけれども、改めて、今のこの研究課題とした理由について、特にその線引きが難しいという点ですとか、あるいは他の障害との兼ね合いについてとはどういう意味なのか、伺いたいと思います。","respondent":"松山障害者支援課長","answer":"そのほか財源確保等もありますけれども、手当についてはどういった経済的な支援が必要かについては、幅広く今後また引き続き検討してまいりたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"こちらは２,０８９人の対象に対して、仮に全部出しますと３億８,４００万円と。ところが、精神障害の方は、今、１級の方だけですから、僅か５.０２％ともう大変限られているということで、これはちょっとあまりにバランスを欠いていると思うので、少なくとも２級まで拡大したとしても４８.４３％の方が対象になるということですから、ぜひ拡大が必要だと思いますけれども、最後にいかがでしょうか。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられる人数比や支給額のみだけで考えることではございませんので、総合的にこちらのほうは検討していきたいと考えております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"よろしくお願いします。それで、いよいよ重層的支援体制が、令和７年度から本格実施ということになりますけれども、この重層的支援体制の状況、人材育成の研修とか、また職員向けの対応マニュアルなど、そうした準備はしっかりされているのか、現時点でどのように進んでいるのかをお伺いをいたします。","respondent":"東野福祉計画課長","answer":"この後、管理職向けの研修も順次進めてまいりまして、この重層的支援体制整備事業の人材の育成という面では図っていかれるように対応してまいります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。この指標の対応方針を決定したケースということを指標にしていいのか、その辺り、今後のその評価のあり方についてお伺いをしたいと思います。","respondent":"東野福祉計画課長","answer":"事務事業評価シートの目標とする件数が半減しているという部分ですが、こちらにつきましては、これまで令和４年度から支援会議と呼ばれる会議で、実際にどういう対応をしてきたかというものを基に、実際に行われるであろう件数を見込んだものです。","id":"exchange-021"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。いよいよ令和７年度から本格実施ということです。実際、始まってからでないと分からない面もあるかと思いますので、今後も現場ではいろいろ起こり得るかと思いますけれども、ぜひしっかりとした対応をお願いしたいと思います。支え愛ほっとステーションで救急代理通報システムをご紹介していると思うのですけれど、そこでは利用に月額３００円かかるということが書いてあります。","respondent":"東野福祉計画課長","answer":"救急通報代理システムですが、こちらにつきましては、本年４月からそれまでかかっていました３００円の利用料金を無償化したものです。委員がご覧いただいているパンフレットの作成時期が、もしかしたら昨年度のものかと思われます。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問","question":"現在はもう無料になっているということで、分かりました。ボランティア、地域支援員が実際この現場で対応されていると思うのですけれども、今後需要が見込まれるのかなと思っておりまして、ですがその一方で１３０人の方が登録されることを目標とされているのですけれども、今後、この地域支援員はボランティアで足りるのか。その辺り、利用者の状況というのをお伺いをしたいと思います。","respondent":"東野福祉計画課長","answer":"現在令和５年度末におきましては、合計５３６名の地域支援員の方がいらっしゃいます。今後、事業につきましてはどんどん地域の中で活動的になってまいりました。コロナが明けまして、その活動も活発になってきたところを受けまして、地域支援員を募集しています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。本当に需要がある今後もっと増えてくる事業だと考えていますので、ぜひ周知のほうも徹底していっていただきたいと思います。現在周知方法についてどのようになっているのか、最後にお伺いいたします。","respondent":"東野福祉計画課長","answer":"こちらの支え愛ほっとステーション事業につきましては、区のホームページのほか、委託しております品川区社会福祉協議会のホームページ、または区の広報紙などでも特集号を組んだり、それから各地域センターでのぼりを立てたり、そういうことでの周知を図っているところです。","id":"exchange-024"},{"speaker":"せらく委員","kind":"確認","question":"私からは、２６９ページ、区立保育園費、２７９ページ、私立保育園経費の運営費から質問いたします。２８５ページのオアシスルームの運営について質問いたします。保育園費の部分なのですけれども、産前産後休暇中の保育についてです。こちらについていま一度確認させてください。延長保育の利用登録には出産要件で登録が可能と確認したのですが、こちらも認識が合っていますか。お願いいたします。","respondent":"芝野保育入園調整課長","answer":"保育時間についてのご質問です。妊娠出産項目について、標準時間もしくは短時間を選べるかというご質問ですが、令和４年度のご案内までは、妊娠出産、当時は産休と申し上げておりましたが、こちらと育休と同じ項目とし、原則９時から１６時と記載させていただいておりました。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問・要望","question":"確認いたしました。こちらについて、産後に上の子の保育園のお迎え時間がどうしてもご家族の都合で６時半以降、延長にかかってしまうという方からご相談を受けました。園と保護者の信頼関係を守っていきたいと思っているのですけれども、区としてはどのような思いで、産休中は標準時間を選択できるようにしたのでしょうか。思いをお聞かせください。保育現場からの声を把握していたら教えてください。","respondent":"芝野保育入園調整課長","answer":"標準時間、短時間ともちろん選べるという形になりますが、やはり産後なかなか今までの状態に戻らないというような状況をいろいろ現場のほうで聞かせていただきながら、個別に相談に乗りながら対応を図ってまいりたいと思います。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。保護者の方へも、現場へも、しっかり周知をしていきたいというお答えをいただいたかと思います。こちらはニーズに応えて変更をしていただいたと思いますので、いま一度、保護者の皆さんが萎縮することなく選択できるように、こちらも各園への周知をお願いしたいと思うのですけれども、いかがでしょうか。","respondent":"芝野保育入園調整課長","answer":"来年４月から年齢制限を撤廃しまして、育児休業期間中は保育園の利用可能になるですが、こちらは短時間のご利用としています。育児休業中の標準時間選択制の導入につきましては、今後の運営状況や他区の動向を踏まえながら検討を進めてまいりたいと思います。","id":"exchange-027"},{"speaker":"せらく委員","kind":"確認","question":"入園関係でもう一つなのですけれども、保育園入園書類の中に、今、希望園を８園まで書くことができることを確認しています。六、七年前は６園だったように記憶をしているのですが、増やしたのであれば、増やした理由を教えてください。通える範囲でもっと園があったので記入したい、記入欄を増やしてほしいというような声があったのですけれども、改めて増やした理由をお聞かせいただけると助かります。","respondent":"芝野保育入園調整課長","answer":"その背景としましては、平成２７年度に子ども・子育て支援新制度が創設されまして、私立園の新規開設の増加が見込まれたということで、記載できる園を増やす対応をしたものです。","id":"exchange-028"},{"speaker":"せらく委員","kind":"確認","question":"最後にオアシスルームについてなのですけれども、在宅子育て支援として、令和５年度の一時預かりについて２万１,７７１人の利用実績があると確認いたしました。今年度の目標は３万６２３人ということで、施設の利用者にはまだ余裕がありそうだなと感じています。ウェブで予約できますし、キャッシュレス決済にも対応していて、１時間５００円で利用ができる。こちらについてご説明いただければと思います。","respondent":"藤村子ども育成課長","answer":"幼稚園につきましては、基本的には長期休みというものがありまして、その間の預かり、リフレッシュといった観点からご利用いただいている形ですが、保育園の方につきましては就労支援という形になるとちょっと目的がずれるというところもありますので。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。やはり保育園に通っている方も土曜日・日曜日でこういったサービスを利用したいという方もいらっしゃると思うので、そういったところを一度調査などをしていただけたら助かるのですけれども、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"利用区分というか利用方法のお話かと思います。現状マッチしていないところといいますか、区民の方からも、例えば保育園に通われている方で、土曜日……終わります。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"私からは、２６１ページ児童相談所移管推進事業、２６７ページ子どもの未来応援事業についてお伺いいたします。１点目に、子どもの未来応援事業についてお伺いいたします。しあわせ食卓事業について簡単に教えてください。","respondent":"飛田子育て応援課長","answer":"しあわせ食卓事業についてです。ふるさと納税によるガバメント・クラウドファンディング等を利用することで、子どもの食の支援を進めるにあたり、ひとり親家庭等へ食品等の配送をきっかけに、就労支援、学習支援、住宅入居支援等につなげて、最終的には自立を支援しております。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"睡眠時間は４から６時間くらいで眠る暇がない。スペシャルボックスでは、ケアする人をケアすることを大切にする工夫がされておりますが、しあわせ食卓事業におきましても、区だからできる範囲において、精いっぱいのあなたが大切なのですという思いをひとり親家庭の保護者や子どもたちに行為と物の両面で今後も全力で伝えていってほしいと要望いたしますが、区のご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"昨年度は食品配送２回のほか、企業寄附により日用品の発送やお米なども発送することができました。引き続き、あなたが大切なのですという思いを込めながら実施したいと思います。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"あなたにおいしいものを食べてほしいの。２点目に、児童相談所移管推進事業についてお伺いいたします。通学したいかどうか意向を原則確認しているのは、児童相談所を持つ７９自治体のうち約３割の２５自治体で、学校で教育を受ける権利が十分に保障されているとは言えない状況が浮かび上がったとあります。現在一時保護所において、子どもたちに対して通学の意向をどのように確認していますでしょうか。","respondent":"金子一時保護担当課長","answer":"保護児童の通学はできる限り実施していく方針で、通学を前提として、送迎の職員体制や通学費用を組んでおります。奪還の恐れや学校が負担である子どももいるので、すべての子どもにはなりませんけれども、子どもの意向を聞き取り、個々の状況を踏まえ通学を実施していきます。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"現状を教えていただきましてありがとうございました。高校生の通学を調整していただいているということで、ぜひそのまま進めていただきたいと考えています。これからできる限り子どもたちが通学することのできる体制整備をお願いしたいと思いますが、今後の見通しをお聞かせください。","respondent":"金子一時保護担当課長","answer":"ただ、もちろん子どもの意向だけに限らず、例えば通学にあたっては学校の理解が必要で、一時保護所から学校に行くということをほかの子どもたちや学校の先生方にきちんと理解いただかないと、子どもが行ったところでやはりとても苦しい状態になってしまったりするので。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"調整はとても大変な部分があるかと思うのですけれども、東京都で視察した際に、葛飾区だったか豊島区等でもお伺いしたのですけれども、ＩＣＴのタブレットの利用を今後どうしていくかというようなことなども、課題としてあるとお聞きしました。様々な手法で子どもたちの教育の権利の保障について、品川区として進めていっていただきたいと思いますので、最後に一言お願いします。","respondent":"金子一時保護担当課長","answer":"様々な形で登校、それから教育の保障、児童相談所の中で通学できていない子どもたちに対し、元教員の学習指導員が保護所内で教育を行っていまして、今タブレットの使用についても今後検討していきたいと考えています。","id":"exchange-035"},{"speaker":"えのした委員","kind":"質問","question":"どうぞよろしくお願いいたします。私からは、２４７ページ認知症理解促進事業、２４３ページ熱中症等予防対策についてお伺いいたします。当日は同じ会場の別の部屋というんですか、シルバー成年式やシルバーフェスタ、こちらが同時開催されていました。これには何か意図があるのでしょうか、お伺いいたします。","respondent":"樫村高齢者地域支援課長","answer":"今後につきましても、来週１０月１３日日曜日に予定しておりますオレンジフェスタですとか、また来月のフレイル予防フェスタのイベントにも併せての実施を予定しています。","id":"exchange-036"},{"speaker":"えのした委員","kind":"質問","question":"私も体験をさせていただきましたが、無料で骨密度や体脂肪のチェックなど様々できて、シルバーフェスタの内容も充実していたと思います。さらに最後、これは防災備蓄品のお土産付きというのですか。開催方法もよい方法だと感じております。改善の余地があると思いますが、いかがでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"こちらも、なるべくやはり多くの方に興味を持っていただきまして、気軽に足を運んでいただきたい事業ですので、今後は会場とも協議を重ねて、できる限りのＰＲなどをいたしまして、区民の方の目にとまるように工夫をしていきたいと考えています。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問","question":"対象者１,０００人に向けてこちらの受診をされて認知症と疑われるような結果が出た方には、その後どのように対応しているのか教えてください。","respondent":"樫村高齢者地域支援課長","answer":"本事業につきましては、認知症への理解促進も大きな目的の一つであると認識しておりますため、参加された方には結果と認知症予防に加えまして、認知症ケアパスのしながわオレンジガイドですとか認知症講演会、それから認知症フレイル予防事業のご案内をするほか。","id":"exchange-038"},{"speaker":"えのした委員","kind":"質問","question":"私も頭の元気度チェック、これは担当の方と対面で１０個の単語を復唱して覚えると言ったらいいのかな。それを思い出して、思い出す作業を３回続けて行ったり、あと３つの動物の中からちょっと仲間が違うのではないかと思うものを１つ答えるですとか、本当に一生懸命覚えました。それでもの忘れ検診、こちらの受診率の推移、また受診率を上げるために工夫等を何かしているのか教えてください。","respondent":"樫村高齢者地域支援課長","answer":"併せて広報しながわ等でも周知を頻繁に図ったりですとか、受診機関を増やすなどの対応をしながら、区としても積極的に対応しています。","id":"exchange-039"},{"speaker":"えのした委員","kind":"質問","question":"私も先日質問しましたけれども、しながわ水族館無料入場券、これは大変魅力的だと思います。頭の元気度チェック、あともの忘れ検診、こちらは認知症の早期発見と早期治療に効果があり、高齢者の健康寿命が長くなることはもとより、介護保険料の制御にもつながると考えているので、事業継続、かつ対象者の拡大などもしていただいて、区として今後の展望などどのようにお考えでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"今後の方針についてです。こちらにつきましては、今年度の実績ですとか受検者からのお声などを踏まえまして、また品川区医師会・荏原医師会の先生方からの専門的なご意見も頂戴しながら、慎重に検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、高齢者施設における避暑シェルター、こちらを通じた多世代交流について、コロナ禍ではシルバーセンターやゆうゆうプラザの利用が一部制限されるなどして、利用人数が下がったと認識をしております。令和５年５月にコロナが５類に移行されましたが、シルバーセンターやゆうゆうプラザの利用人数に変化はありましたでしょうか、お知らせください。","respondent":"樫村高齢者地域支援課長","answer":"それでも、コロナ禍以前の利用者数にはまだ届いていない状況ではありますけれども、今後さらに事業の充実等も図っていきまして、利用者が増加していくものと見込んでいるところです。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"今年の夏は本当に昨年に引き続いて猛暑日が多く、特に高齢者の方などは熱中症が懸念されました。シルバーセンターやゆうゆうプラザなどの高齢者が多く集う熱中症対策は、どのように行っていますでしょうか、お知らせください。","respondent":"樫村高齢者地域支援課長","answer":"さらに今年の夏は猛暑ということもありまして、８月の上旬からシルバーセンターの１室を避暑室として開放するとともに、ペットボトルの水も配布いたしまして、高齢者の方をはじめとした区民の皆様に熱中症対策を行ったところです。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"今年の避暑シェルターの利用者数、こちらはどのくらいだったのか。今回、シルバーセンターで使った避暑室は、ふだんこちらはどのように利用されているのか教えてください。","respondent":"樫村高齢者地域支援課長","answer":"９月以降におきましても、マッサージサービスで使用する日以外の日を避暑室として開放しています。","id":"exchange-043"},{"speaker":"えのした委員","kind":"意見","question":"私ものぼり旗に誘われて、今年の夏、平塚橋のゆうゆうプラザを利用させていただきました。大変有効的な使い方だと理解をいたしました。これから来年度の展開などがありましたら、お考えをお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"いずれにせよ、引き続き高齢者の方をはじめとしました区民の方の効果的な熱中症対策になるように努めてまいりたいと考えています。","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"これは私ももちろん利用させていただいたのですけれども、避暑シェルターの利用対象者、こちらについてもお知らせいただけますでしょうか。高齢者だけなのか、また近隣の方であれば誰でもいいのか、その辺をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"利用対象者ですけれども、高齢者に限らず地域の方、小学生などどなたでも利用可能です。現場から、小学生などが涼を取りに、また麦茶を飲みに施設へ立ち寄ることも頻繁にあると聞いております。","id":"exchange-045"},{"speaker":"えのした委員","kind":"確認","question":"ちょうど平塚橋ゆうゆうプラザは学校に近いので、小学生の熱中症対策にも利用できるということで、利用者制限なしで利用可能ということを確認できました。これは避暑シェルターをきっかけに、多くの多世代交流の場につながると考えますが、区のご見解をお知らせください。","respondent":"樫村高齢者地域支援課長","answer":"区としても、区民が利用しやすい避暑シェルターにしていきたいと考えています。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"私からは、ページで言うと２４７ページ高齢者活動支援事業と、それから２３３ページ地域生活支援事業、こちらは障害者の住宅あっせんというようなことについて伺いたいと思います。そういった中で、この第３回定例会の補正予算の中で、軟骨伝導補聴器の窓口への配備ということで、３５台の購入費というのが計上されました。この２つの窓口に配備をしたときの区民の反応等を伺いたいと思います。お願いします。","respondent":"樫村高齢者地域支援課長","answer":"利用者の具体的なお声としましては、「どの年代でも使用しやすいと感じたです」とか、「とても聞こえやすくてびっくりした」、「今後も窓口などで活用が進むことを期待する」といったようなお声があった一方で、こちらは補聴器をふだん着用される方ということなのですけれども。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう一つは、住んでいる場所とか名前という個人情報に関わることは、やはり窓口でやり取りが起こる。ただ、こういうところ以外でも高齢者の方が訪れて、例えば税務課とか戸籍住民課とか、こういったところで個人情報をやり取りするような場面というのがきっとあるのではないかと思うのですけれども、こういったところへの配備についての考えをお聞かせいただきたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"こちらの５台につきましては、委員がおっしゃられたように例えば税務課ですとか戸籍住民課ですとか、そういったところへの貸出しを目的としまして５台計上しておりますので、そういったところにも活用いただきまして、そういったところの活用状況等を見ながら。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"地域生活支援事業ということで、障害者の方々への住宅あっせんというところで、事業そのものは住宅課の入居促進と連携した事業ということでありますけれども、本日は民生費ですので、障害者福祉課に関わるところで質問させていただきたいと思いますけれども、まずこの障害者の方の入居促進、あっせんでの実績がここのところ数年ないというところがあるのですけれども。","respondent":"松山障害者支援課長","answer":"現在の要件緩和について、相談事業所を通じて周知しているところですが、ご利用いただけるよう、継続して積極的に周知を図ってまいります。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"障害の特性にもよりますけれども、その辺の認識についてはどうなのでしょうかというところと、そういったことについて、区として支援というのは考えているようなところがあるのか、お伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"例えば内見地が不動産屋への同行支援、入居後の光熱費の手続支援等、例えば伴走型の居住支援が必要ではないかということを考えておりまして、支援策については今後検討してまいりたいと考えています。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"今支援策を検討していただけるということで、ぜひここはかねがね会派としても高齢者も含めて課題と捉えていたところですので、ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。は障害者福祉施設等整備費についてお伺いいたします。今年４月に開設しました出石つばさの家についてお聞きします。こちらは定員が１７名ですが、６か月たちまして、現在の入所の状況はいかがでしょうか。入所された方の障害区分の平均値は今のところどれくらいでしょうか。今後小山七丁目、戸越四丁目が控えておりますが、それぞれの進捗について併せてお聞かせください。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"私からは、出石つばさの家の入居状況についてご説明申し上げます。９月３０日時点で、定員が１６人です。お１人はショートステイということになっておりますので定員１６人。１６人のところ、１２人の方が入居に至りました。現状、小山七丁目のほうは来年、令和７年度の開設をめどとしまして、現在運営をする予定の事業者のほうで建設の設計ですとか、それから工事等の進め方について調整を行っているところで。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"民間の方の力も借りながらしっかりと寄り添っていただけたらと思います。続きまして、国民健康保険社会保障・税番号制度システム整備費補助金からお聞きいたします。現在品川区民のマイナンバーカードについて、マイナ保険証としての登録率、医療機関での使用の割合についてお聞かせください。","respondent":"池田国保医療年金課長","answer":"１点目のマイナカードの取得率、それとマイナカードの利用率についてお答えします。品川区民のマイナカード取得率は７割ほどでございまして、国民健康保険のマイナ保険証の取得率については４８.１４％という形になっております。マイナカードの利用率につきましては９.１％。","id":"exchange-053"},{"speaker":"おぎの委員","kind":"確認","question":"今年２０２４年２月の厚生労働省からの通知により、１０月よりマイナ保険証の登録をした方もそれを解除することができ、送られてくる資格確認書を医療機関で使用できるとのことですが、マイナ保険証登録解除の概要について、また品川区ではどのように周知していく予定か、お聞かせください。","respondent":"池田国保医療年金課長","answer":"マイナカードの解除につきましてはまだ国のほうから通知が来ておりませんので、区としての方針が固まってないところです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２８４ページの生活保護費に関わって、エアコン設置など熱中症対策、そして２３３ページ障害者介護給付事務の同行援護について伺います。生活保護ですが、今年も連日猛暑で暑い夏でした。東京都監察医務院によると、熱中症の疑いで亡くなった方は、８月までの３か月間で２４８人と過去最高です。エアコンが壊れた際にも設置できるように支援をしていただきたいと思いますが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"エアコンについてです。本年度も令和６年５月３１日だったかと思いますが、国から事務連絡が出ておりまして、エアコン設置についてはこのようにしなさいということが書かれてあります。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"国からは特に出ていないということですけれども、実際問題、今エアコンなしでこの夏生活をしていくということは、本当に困難だと思います。ぜひ設置ができるように、国にも働きかけていただきたいと思いますし、その中で区としてできることをやっていただきたいと思いますが、いかがでしょう。","respondent":"豊嶋生活福祉課長","answer":"そのエアコンについてですが、生活保護を受けている方につきましては、一定の基準を満たせない、要は条件から外れた方に関しましては社会福祉協議会の貸付け等々を今適切にご案内をしています。そういった対応を引き続きしてまいりたいと考えております。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"全国でも暑い年には１,５００人もの方が熱中症で亡くなっている状況です。本当に深刻な問題だと思いますので、エアコン設置できるように、壊れた後も設置できるようにしていっていただきたいと、これは要望しておきたいと思います。夏季加算の実施を国に要望すべきです。いかがでしょうか。併せて、国が実施するまでは区が独自に支援をすべきだと思いますが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"要望ですが、こちらにつきましては確かに昨今のこの暑さ等々ありますので、他区の状況も見ながらその辺りは慎重に検討してまいりたいと考えています。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"国の受託事務だからできないということなのですけれども、そこはぜひ国に強く要望していただきたいと思いますし、区としてもやはりやっていかなければ、この生活保護の方も生活できないということになっていきますので、ぜひそこは区としてできるところを考えていただいて、実施していただきたいと思いますが、改めて伺いたいと思います。","respondent":"豊嶋生活福祉課長、菅野高齢者福祉課長","answer":"そうしたことから考えまして、法定受託事務というところから、特別な加算というのは区では現在考えてございません。毎年これは７月から９月ということで行わせていただいておりまして、その中で、エアコンをつけていらっしゃらない方がどういう状況なのかというところも十分聞き取らせていただいた上で、施策として研究していきたいと考えています。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として独自の加算はできないということですが、やはり国にもしっかり求めていただいて、この収入認定もされないような仕組みもぜひ考えていただきたいと、これは要望しておきたいと思います。視覚障害者福祉協会の皆さんと懇談させていただいて、いただいた要望を求めたいと思います。現在どうなっているのか、もうこれは始まっているのか、始まっている場合はこの間の実績を伺います。","respondent":"松山障害者支援課長","answer":"重度障害者就労支援特別事業の実施状況です。本年７月から開始いたしまして、９月末時点で３人の方がご利用されていらっしゃいます。３人のうち、お２人がシルバーセンターでのマッサージに従事されている方です。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"必要な方がしっかり利用できるように、事業所に周知徹底をしていただきたいと思いますが、いかがでしょうか。併せて、緊急時に同行援護のガイドヘルパーが利用できるようにしてほしいということで、急な病気や親類の不幸などに対応できるようにしてほしいということなのですけれども、緊急時のガイドヘルパーが利用できる、こうした仕組みをつくっていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"重度障害者就労支援事業の周知につきましては、同事業開始にあたりまして団体や相談事業所へお知らせをしています。","id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"最初に、出石つばさの家整備費について質問をします。先ほど、おぎの委員から区分についてのご質問があり、答弁が返ってきましたので、それ以降の内容について聞かせていただきたいと思います。担当課に確認をさせていただいたところ、点数は一緒でも区分６から優先的に面接をして進めている状況だとは確認をさせていただきましたが、このような区民の方のご意見に対する区の見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"審査会につきましては、医師や障害者団体の代表の方、外部委員も入っている中でのご意見を伺い、区が最終的には決定したものですが、今後入居調整指数を採用する際には、委員よりいただいたご意見につきましても審査会でお諮りをして、ご意見を伺ってまいりたいと考えております。","id":"exchange-061"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ検討をしていただきたいと思います。この入居調整指数の見直しだけではなく、グループホームの入居申込面接の際には、利用者をよく理解している相談支援専門員の参加も有効だと考えますが、その点についてはいかがでしょうか。","respondent":"松山障害者支援課長","answer":"ただ、必ずしも障害者相談員を同席させたほうがいいのかどうかにつきましては、ご本人やご家族のご希望によるものだと考えております。","id":"exchange-062"},{"speaker":"ひがし委員","kind":"提案","question":"現場を知っている方の参加というところは、ご家族にとっても負担軽減になるのかなと思いますので、向こうからの提案だけではなくて、こちらからもどうですかというようなお声かけをしていただけるのもいいのかなと思います。ぜひ、その点については要望しますので、ご検討ください。次に、障害児通所施設の放課後等デイサービスについて質問をします。","respondent":"松山障害者支援課長","answer":"これは児童発達支援も同じでして、児童発達支援放課後等デイサービスのうちで、重症心身障害児または医療的ケア児に対応可能な障害児通所支援事業所に、区独自で１事業所５００万円助成をしています。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区でも区独自の支援・助成を拡大してくださっているということで評価をいたします。この助成、年々利用件数が増えるように、区としてもお声がけ、周知を徹底していただきたいと思います。もう一点、事業所数の増加に伴って、次の課題としては質の担保ということも重要な課題になると思います。その点について、区の取組、見解をお答えください。","respondent":"佐藤障害者施策推進課長","answer":"この１０月には児童相談所の区への移管に伴って、放課後等デイサービスも含めました障害児通所支援の事業所の指定権限も移管されております。開設から運営について指導助言を行いまして、サービスが適切に提供されるよう、引き続き体制を整えてまいりたいと考えております。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"児童相談所からの件があって、区としていろいろと指導ができるようになるというところで、体制整備ということもすごく大切だとは思うのですけれども、区と連携して医療的ケア児の方々、そしてご家族の方々の支援というところを評価をしていただきたいと考えています。以前から、品川区では医療的ケア児等への支援に関わる情報をまとめた冊子等がなく、作成をしてほしいと要望しています。","respondent":"中島保育施設運営課長","answer":"効果といたしましては、受入可能な医療的ケアの項目、入園の流れなど、医療的ケアが必要な情報をコンパクトにお伝えできるようになりましたので、説明を受ける側にも説明する側にもメリットがあると感じているところです。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらの中を見させていただきました。その点について、障害者支援課、前回は福祉部長からも情報発信については重要だと考えている、医療的ケア児連絡会等で意見を伺いながら検討していくというようなご答弁がありました。現在の検討状況、ぜひこのようなサポートブックについても私は必要性を感じておりますので、作っていただきたいと考えていますが、ご見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"作成にあたっては、医療的ケア児等の関係機関の連絡会の委員の方々から挙がった意見を頂戴しながら進めていきたいと考えております。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"大変前向きなご意見・ご答弁いただきまして、ありがとうあります。１点、その中に災害というところも入れていただきたいとこちらは要望させていただきたいと思います。災害時にどうしたらいいのかというところについて、他区だとその内容も１ページ盛り込んでいるというようなところがありまして、それを見ていてとても分かりやすくていいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"２４５ページ、高齢者福祉施設支援事業に関連して、南大井のさくら会について、１階玄関隣の「ぽこあぽこ」の再開を求めて質問したいと思います。現在は、物置や職員の休憩所になっているという話も伺いました。そこでまず、「ぽこあぽこ」の営業が中心になった理由を伺いたいと思います。ぜひ様々な条件や環境を整えて、この喫茶コーナーを再開していただきたいと思いますが、いかがでしょうかと。","respondent":"菅野高齢者福祉課長","answer":"さくら会南大井複合施設における、「ぽこあぽこ」についてご質問にお答えします。平成１２年５月にこの施設が開設時から、「ぽこあぽこ」の名称で、品川区手をつなぐ育成会が、施設エントランスの顔として、にぎわい、集い、喫茶、食事の提供を行っておりました。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"ドリップ式のコーヒーでとても好評だと伺っております。こうした喫茶コーナーが様々な交流の場だったり、理解を広げる場だったりになっている、そのような場があることの意義というのでしょうか、そのこと自体は、区はどう思っていらっしゃるのか、ぜひ区の支援も含めて、課題を整理して、何とか再開できる形を改めて求めたいと思いますけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"現状の利用で十分な満足も得ており、特段の問題もないというさくら会の方針でもありますので、区としては、そういったカフェの場が決して必要でないということではなく、この場所においては違う形で今運営していただいているということで捉えております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"かつてそのような場所があって、様々な理由があって今中止となっているということ、現在は障害がある方の訓練の場だったり、就労の場だったり、そのような形ではなく、何らかの形で使われてはいるものの、さくら会ができた当時からある施設でありますので、ぜひ様々な枠組みや支援の形を見ていただいて、法人がそのままでいいとおっしゃっているところは困ったものだなとは思いますけれども、ご近所の方。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、２４９ページ、高齢者向けパソコン・スマホ教室についてお伺いいたします。高齢者向けパソコン・スマホ教室の中身をお聞きしたいと思いますが、入門編は、１コースで４回、ワンポイントは１コースで１２回でそれぞれの１回ごとの費用が、入門編のほうは１万６,９５０円、ワンポイント編は５万円でございました。","respondent":"樫村高齢者地域支援課長","answer":"こちらの委託料、１回当たり５万円ですけれども、高い理由としまして、こちらの講座内容が高齢者に多い疑問やニーズを扱う内容となっておりまして、その都度テキストの作成を行う必要があるほか、講座開催の当日においても、個別に対応ができるように。","id":"exchange-071"},{"speaker":"こしば委員","kind":"質問・要望","question":"個別具体的な対応が求められ、その都度テキストを作らなければならない、そういった事情があるということで、この値段設定であったということは承知をいたしました。その講座、ワンポイント編のものなのですけれども、意図するそもそもの目的というようなものがどのようなものであったのか、また、実際の当時の稼働率についてお聞かせ願いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"年間通して１２回、全体で開催を予定したところですけれども、応募がなく中止とした回数も４回ほどございました。","id":"exchange-072"},{"speaker":"こしば委員","kind":"質問","question":"年間通して１２回やったけれども、途中でなかなか人が集まらずに中止をしてしまったときもあったということをお聞きいたしました。稼働率が低いことは、その事業を見直す１つの大きな判断の基準となると考えますが、そういった判断の基準を受け、これらの事情を踏まえまして、どのような判断といいますか、見直しをされてきたのか、教えていただけますでしょうか。","respondent":"樫村高齢者地域支援課長","answer":"その代替としまして、需要の高かった入門コース、Ａｎｄｒｏｉｄの入門コースの実施回数を増やしまして、増加する区民ニーズのほうにも対応しています。","id":"exchange-073"},{"speaker":"こしば委員","kind":"質問","question":"そういった判断基準の下で、区民ニーズにまた合わせていくというご答弁のほういただきました。今、様々な教室が行われておりますけれども、本来であれば、区内に住む高齢者の方々が満遍なく教室に通えるような、そういった地理的な、何ですか、環境を整えることも必要ではないかなと考えています。ぜひこれを区内全域に展開されていくことをお願いしたいと思いますが、見解をお聞かせください。","respondent":"樫村高齢者地域支援課長","answer":"稼働率も高いことから、令和５年度には大井３丁目憩いの場、それから令和６年度には平塚橋ゆうゆうプラザの会場を追加しまして、実施場所の拡大を行いながら、現在区内の５会場にて実施しています。","id":"exchange-074"},{"speaker":"こしば委員","kind":"質問","question":"こちらのほうは、そもそもスマホを持っていない方も対象にしたものと伺っておりますが、そうなりますと、なかなかこの入り口のハードルがやや高いようにも思われますけれども、その現場の声では、どういったものがきっかけとなってこういった教室に入られたのか、どういった声があったのかということをちょっと教えていただければと思います。","respondent":"樫村高齢者地域支援課長","answer":"初めてのスマホ体験教室へのハードルですけれども、お持ちでない方にも参加いただけるように、所有されていない方へ、教室実施期間中１か月間の貸出しを行っております。","id":"exchange-075"},{"speaker":"こしば委員","kind":"質問","question":"今の答弁で、１か月間無料で貸出しをして、また、自宅でも無料でインターネットを使えるという答弁のほういただきまして、ありがとうあります。これはまさにデジタルデバイド解消に向けた一歩を利用者自身が踏み込んだものと考えておりますが、そのような中でこの現場の声、また、その体験教室を受けた声、幾つかありましたら教えていただければと思います。","respondent":"樫村高齢者地域支援課長","answer":"教室を受講された方からの現場の声ですけれども、これまで電話しかできなかったが、スマホが日常生活のほうに役立つようになって、生活自体が便利になったといったお声や、また、インターネットでしか予約できない演劇の鑑賞に行けたといったような。","id":"exchange-076"},{"speaker":"こしば委員","kind":"質問・要望","question":"様々ツールを使っていただけて、それでよかったという声をいただいていること、よく承知をいたしました。この事業を含めて、デジタルデバイド、本当に全庁的に取り組んでいただきたいことと思います。予算の規模の増大も含めて、今後全庁的に取り組んでいただきたいことを願いまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"確認","question":"福祉の聡、やなぎさわ聡です。２８７ページ、生活保護経費に関連してと、２３３ページ、障害者グループホーム運営費助成、２４７ページ、外国人介護職員受入環境整備、お願いします。これは３親等までの親族に、金銭的な援助ができないかということを区のほうで確認をするという作業になるのですけれども、現在品川区の扶養照会率というものは何％で、ここ数年の推移はどれぐらいになっているのでしょうか。","respondent":"豊嶋生活福祉課長","answer":"令和５年度、まず申し上げます。扶養照会をした世帯、４４０世帯へ生活保護を開始しておりまして、うち１９７世帯に扶養照会をしました。４４.８％です。今手元にある数字で４年前の数字が一番古いのですが、４年前の扶養照会率は５９.７％となっております。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。１％未満になってしまっているこの扶養照会をかけることによって、ケースワーカーの負担もかかるということで、それがなくなれば、逆に言えば、もっと生活保護受給者の方に寄り添った対応ができると考えておりますけれども、その点で、何か今、扶養照会を含めてですが、ケースワーカーの方の業務上、非常に困難というか、時間を割いている業務というものは具体的に何かありますでしょうか。","respondent":"豊嶋生活福祉課長","answer":"ただ、令和３年の２月の段階で、扶養照会をしても、要はその援助が期待できないもの等々については扶養照会を外してもいいですよ、しなくてもいいですよという見解は出されております。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。ちなみになのですけれども、品川区では、ケースワーカー１人あたり生活保護世帯何世帯を受け持ちというか、担当されていますでしょうか。","respondent":"豊嶋生活福祉課長","answer":"現時点でのケースワーカー一人あたりの受け持ち数ですが、国は８０人を１つの標準数としています。現時点では、８０人を若干下回る７８.７人です。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"個人的に思うことは、例えば高齢者の方のケアマネジャーが、大体一人４０件ぐらいなのです、担当が。いうと倍なのです。当然生活保護を受給するような方というものは、様々な困難が複合的にある方なので、そういった方に対して、やはり１人のケースワーカーで８０件持つということはかなり激務になるのだろうなと思いますので、ちょっと要望ですけれども、ぜひ改善を要望させていただきたいと思います。","respondent":"豊嶋生活福祉課長","answer":"なるべく字数を減らす、字を大きくする、イラストを増やす、なるべくページ数を少なくしてエッセンスにしていくというような流れで、今現在改訂作業を進めているところです。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"厚生労働省が通知しているように、１０年以上音信不通な方や、もしくは相続などでもめているなど、そういったときには扶養の照会が不要ですよというようなことをもし可能であれば明記してほしいと思います。これは要望です。次です。障害者グループホーム運営費助成なのですけれども、これ２４０万円が計上されていますが、詳しい内訳を教えてください。","respondent":"松山障害者支援課長","answer":"２４０万円の内訳ですけれども、有資格者の方に対して助成したものになっております。１事業所なのですが、２名いる資格者の方を配置していたため、その助成ということになります。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これはもともとの見込みというものはいかがだったのでしょうか。もともと２４０万円ぐらいなのか、それより多かったか、少なかったか、見込みと比較して。","respondent":"松山障害者支援課長","answer":"当初の予算としては倍の予算、当初４件を見込んでおりました。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"意見","question":"思ったよりも利用されなかったということで、やはり、介護施設で３年は結構ハードルが高いと思うので、ぜひこれ１年とか、もしくは２年、少し短縮して、今後実施をお願いしたいのですけれども、その辺いかがでしょう。","respondent":"松山障害者支援課長","answer":"有資格者助成については、入居者が中重度で支援がより必要な方に対して有資格者を配置している場合の助成だということで、それらの趣旨も踏まえて、質も担保しつつ、また、あと実務経験等については事業者の声を聴きながら、緩和していく方向で検討をしてまいります。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"意見","question":"緩和していく方向ということで、ぜひ進めていただければと思います。最後に外国人材の受入れなのですけれども、れいわ新選組、私の所属しているれいわ新選組は、移民政策に反対しております。技能実習生や特定技能を含めた外国人の受入れというものに対して、非常に慎重です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"こんの委員","kind":"提案","question":"大変に前向きな取組に、大変に評価をいたします。そこで品川区においても、共生社会の観点から、この認知症にやさしいまちづくりを推進する意味においても、先日一般質問で提案をしました、介護事業所、あるいは介護専門学校以外にも、この認知症サポーター養成講座や介護教室などでもユマニチュードを普及啓発して、導入してはどうかと提案をいたしますが、ご所見を伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらの在宅介護者研修は、委員もおっしゃったとおり、在宅で高齢者の方を介護されている方の対応の仕方等についての、いろいろな講師を、専門家の方を招いて実施している研修となっております。","id":"exchange-086"},{"speaker":"こんの委員","kind":"質問","question":"前向きなご答弁をいただきました。９０分講座で２日間受講するわけなのですが、オンライン講座もやっているのです。こうした講座の受講を希望したいご家族、介護するご家族、こうした方々の支援ということも考えられると思いますが、例えば受講費の助成をするなど、こちらの日本ユマニチュード学会の講座を活用するということも考えられますけれども、こうしたことへのご見解をお聞きしたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"ユマニチュードのオンライン講座の補助についてのお尋ねです。こちらにつきましては、情報収集しながら、区としても研究してまいりたいと考えています。","id":"exchange-087"},{"speaker":"こんの委員","kind":"確認","question":"契約が５年の住宅等もあるということもお聞きしているのですが、この契約期間が住宅によって差があるというところ、どのような契約の期間の考え方になっているのか確認したいということと、また、契約期間に上限、期限あるのか、オーナーが契約を更新したいとなればずっと更新できる話なのか、今後もこの７棟の借り上げ住宅を維持していけるようになっているのか。","respondent":"樫村高齢者地域支援課長","answer":"２回目以降につきましては、１０年で更新しているといった考えです。今後継続していけるかどうかといったところですけれども、住宅の状態を見ながら、オーナーとも協議を重ねて、契約更新をしていくような考えです。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問・要望","question":"オーナーと状況も確認をしながらということですが、そうすると、５年契約となっているところも、いわゆるオーナーのご希望で５年としているのでしょうか。その辺も、いま一度お聞きしたいと思います。そこで、移転先の選択肢として、公的住宅の必要性が高いと、このように捉えていますので、今後この捉えたことに対しての対策、具体的に何か考えていることがあればお聞かせいただきたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"需要の高さというものは区としても認識していますが、委員の先ほどのご発言の中にもありました民間住宅のあっ旋事業、すごく今伸びているところですので、こういった事業を活用しながら、公的住宅と民間住宅へのあっ旋を積極的に行いまして。","id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、この事業の詳細はこれから出てくるとは思いますが、今後増加する傾向にある、この公的住宅の必要性に応えるためにも、区が借り上げる居住サポート住宅として供給を推進していく、こうしたことも必要だと思いますけれども、その点について、福祉の観点からのご所見を伺いたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"公的住宅の必要性ですけれども、先ほど委員おっしゃられました住宅セーフティネット法の改正に伴いました居住サポート住宅、これから出てくると思いますが、こちらにつきましては、先ほど委員おっしゃられましたように、住宅課の所管となっておりますので。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ住宅課と連携をして、この公的な住宅の確保、こうしたことを進めていただきたい、このように思います。次の質問に参ります。こちらはこの取得費用ということよりも、利用者の声として、利用したい日時のご希望に合わない場合、何件もドゥーラを当たらなければいけないというような状況が起きているというように、利用者からの声がありますが、そのようなお声は入っておりますでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"本助成事業につきましては、利用者アンケートのほう取っておりまして、満足度としては、９割を超える方が満足をいただいているという、非常に好評いただいている事業であるのですけれども、一部利用に際して、委員のお話にあったマッチングや。","id":"exchange-091"},{"speaker":"こんの委員","kind":"意見","question":"アンケートのお声から改善を考えてくださっているということですので、マッチングの改善をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、２４５ページ、福祉人材確保・定着事業、２３０ページ、障害者支援費の中の障害児支援について、時間があれば２８５ページ、在宅子育て支援拠点事業についてお伺いをしていきます。初めに福祉人材ですが、これまでも様々取組をされてきたと思いますけれども、令和５年度の決算において、令和５年度の実績がどのようになっていたのか教えてください。お願いします。","respondent":"菅野高齢者福祉課長","answer":"外国人介護職員受入環境整備や、専門学校の広報活動強化事業助成、そしてＩＣＴ見守りシステム設置や、あとは介護福祉士の実務者研修の受講費の助成、そして介護職魅力発信事業と、多岐にわたった事業内容で。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる人材定着のところで、アからオというものがありますよね。これはやはり、なかなか現場に即していない支援策ではないのかなと考えています。今年度から実施をされている、特別養護老人ホーム、老人保健施設における介護職員確保支援、これについては現在約半年、半分ですか、年度の半分ぐらいが経過したのですけれども、この事業についての実績は今どのようになっているか教えてください。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホーム施設における介護職員確保の支援は、今年度の新規事業ということで掲げしていますが、現在要綱の整備等させていただいて、間もなく事業開始の運びとして組み立てているところです。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その後いくら人材を確保しても、ではその紹介料をどうやって事業費から賄っていくのかと、これなかなか難しい。ですから、ここはやはり現場の声をしっかり聴いていただいて、現場に即した支援事業にぜひしていただきたいなと思います。これは要望で終わりますけれども、よろしくお願いします。この障害児の支援について、現在品川区で所得制限がかかっているものがあるのかどうか教えてください。","respondent":"松山障害者支援課長","answer":"現在、品川区で所得制限がかかっているものは、障害児福祉手当になります。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ただ、品川区として、様々当事者の方たちからもお声を聴いているのだと思います。ですから、ぜひその辺は国にしっかりと声を上げていただきたいと思いますし、やはり障害児の、いわゆる福祉に関しては、子どもの家庭の所得の状況によって、不支給だったり、支給額に差異が生じたりすることのないように、ぜひそのような思いで、区としても取り組んでいただきたいなと思いますが、これも要望で終わります。","respondent":"藤村子ども育成課長","answer":"今在宅で子育ていただいている方の割合というものは、すみません、おおむね２万人中の、半数弱だったと思います。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問","question":"私も大体半分ぐらいかなと思っています。そのような中で、この決算書を見ていても、いわゆる在宅で子育てをされている方とそうでない方の世帯が受けている恩恵というものは、結構な差があるのではないかなと思います。やはりそこに光も当てていって、在宅で子育てもできるのだよという環境づくりを行うことは、必要だと思うのですが、その辺区として考えがあれば教えてください。","respondent":"藤村子ども育成課長","answer":"区としての考え方というところですが、在宅で子育てされている方にも何かこうインセンティブを、というところかと思いますけれども、例えば今八潮の子育て支援施設というものを計画しておりますが、そういった中で、在宅で子育てされている方も楽しんで子育てできるような環境や。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう感覚としても、やはり在宅子育てをされている世帯が受ける恩恵というものは、今の時点では限られているので、例えば在宅子育て支援金など創設をするだとか、そのようなことによって、子どもを家で育てようかな、どうしようかなと思っている方たちにも対応ができるような制度設計というものは、改めて、今このような時代だからこそ考えていただきたいなと思いますので、ぜひそういった視点も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"２６７ページ、ひとり親家庭支援事業、時間が許しましたら、２６８ページの児童保育費全般から伺いたいと思います。ひとり親家庭支援の広がりを要望したく質問します。区民の方から窓口の対応に感謝の声が届いております。今、離婚相談は増えているのでしょうか。令和５年度、どのようなご相談が多かったのかを併せて伺いたいと思います。ひとり親相談係で行っている家庭相談は、元家裁調査官の方です。","respondent":"飛田子育て応援課長","answer":"家庭相談員の強化については、もちろん枠を増やしていくということも近々の課題とは思っておりますが、離婚前後という視点でいえば、離婚の問題だけではなく、離婚後にひとり親になったときの支援、就労支援、生活支援など、家庭相談員だけに頼ることなく。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問・要望","question":"まさにこの区民の方も、家庭相談、母子職業紹介、ＤＶ相談、ひとり親支援担当など、様々な窓口を訪れたとおっしゃっておられました、手続の簡素化とともに、ひとり親支援に関わる窓口のワンストップ対応をお願いしたいと陳情をいただいております。私も何とかしたいと思っています。そこで今、全庁的に行政のＤＸ化を進めていただいています。この辺り、区のお考えと対応を伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"現在ひとり親家庭休養ホームの事業については、窓口の申請だけになっておりますので、今後電子申請を受け入れられるように検討していきたいと考えております。","id":"exchange-100"},{"speaker":"西村委員","kind":"質問・要望","question":"この離婚手続にどれだけ気力と体力を使うのかということを、私も陳情を伺いながら本当に痛感をしております。家庭裁判所では、養育費や婚姻費などの申立ても全て郵送でいいということを私も初めて知りまして、聞き取りは電話対応で大丈夫というように確認を取っております。例えば、課題を解決する１つの方法としまして、国の進める離婚前後親支援モデル事業の導入をご要望させていただきたいと思います。","respondent":"飛田子育て応援課長","answer":"国からも、離婚前後の支援体制強化ということで、講座等の開設についても示されておりますので、他区の実施状況や実施方法などを精査しまして、区としてどのように開催していけばいいのか、検討していきたいと考えております。","id":"exchange-101"},{"speaker":"西村委員","kind":"提案","question":"ぜひご検討いただきたいと思います。もう一つご提案させていただきたいのですが、品川区、大変家賃が高く、離婚とともに引っ越しに悩む区民の方も多くいらっしゃって、母子家庭が住むことは難しいと、お声が届いております。住宅入居支援をしていただいていますが、ほか自治体も参考にしていただきながら、住宅費助成の検討もしていただきたいと要望しますけれども、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"委員のおっしゃる住宅の補助については、今年度より、国のほうも児童手当や児童扶養手当の拡充もありましたので、国や他の自治体の動向を注視していきたいと考えております。","id":"exchange-102"},{"speaker":"西村委員","kind":"質問","question":"ぜひとも多面的にお願いをしたいと考えています。次に、児童保育費全般から、休園判断について伺ってまいりたいと思います。警戒レベル３でお迎え、保護者連絡となり、その他明確に基準をつくっている自治体があります。品川区の今のご判断の基準と状況を伺います。","respondent":"中島保育施設運営課長","answer":"保育園の休園に関するお尋ねです。保育園につきましては、児童福祉法で定められている福祉施設でありまして、閉園に関する一律の規定はないところです。区としましては、できる限り休園せず、最大限登園自粛する方向で考えているところです。","id":"exchange-103"},{"speaker":"西村委員","kind":"質問","question":"そのようなご回答になるかなと思っていたのですが、区内事業者より、８月の、大変嵐の日にご相談をいただきました。現場では、園長先生たちの声も踏まえて、通勤に危険を感じる職員は早めに帰し、それに伴い、保護者にお迎え要請を現場判断で許可をしたと伺っております。明確に基準をつくるなど、ご検討をお願いしたいと思いますが、ご答弁をお願いいたします。","respondent":"中島保育施設運営課長","answer":"当然園児の、保護者そしてそこで働く職員も含めまして、安全確保は非常に重要な問題だと考えております。現時点では、登園自粛という考えではありますが、他区の状況などを含めまして、様々情報把握に努めて、安全確保については慎重に考えていきたいと思います。","id":"exchange-104"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、２４１ページの入院中の紙おむつ代助成事業と、それから２２９ページの障害者福祉施設等整備費について伺いたいと思います。５,０００円という額に対しても、この実施した当初から、２３区平均が６,３００円だったのです。改めて、なぜ所得制限をなくすことになったのか、その理由を伺いたいと思います。２３区で、他区の助成額についてもお聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そして他区の状況ですけれども、５,０００円以上を超える購入費助成をしているところが、２３区中１４区というようになっております。","id":"exchange-105"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからポスター８０枚分が計上されているのですけれども、これがどのように活用されているのか伺いたいと思います。今回、これからいつ頃、この所得制限をなくすことと、額も上げていくということはいつ頃の見通しなのか、そのことも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今後の見通しにつきましては、こちら、あくまでも社会福祉協議会の事業というところですので、まずは見直しを検討してもらって、区としましてはこういったご意見も踏まえて、事業経費に係る支援を積極的にしていきたいというところで、働きかけをしてまいりたいと考えています。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなところで、ＭＳＷの方など、そういうところにもぜひ知らせていただいて、この周知をぜひお願いしたいなと思っています。それから、今年度の社会福祉協議会のチラシを見ると、住民税非課税世帯から非課税者というようになっているのですけれども、これは変わったのかどうなのか、要綱は変わっていないようなのですが、これはどうなのかということを具体的に教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういったところから、住民税の非課税世帯というものもご本人の非課税というところに、社会福祉協議会のほうが処理できるような形で見直させていただいたというところと、今後は、やはり周知の仕方については、社会福祉協議会とともに病院とも連携して、多くの方に。","id":"exchange-107"},{"speaker":"田中委員","kind":"質問・要望","question":"例えばこれまで私立幼稚園には入園料の補助金があったり、あるいは運営費の補助金などがあったりしますが、多く幼稚園側からの要求、要望もあり、また、それに対して査定を行い、区役所としてしっかりこれまで補助を出してきておりましたけれども、この要望に対して、どこまで支出をしていくべきなのかという観点で、まずは今のお考えをお聞かせいただきたいと思います。","respondent":"佐藤保育事業担当課長","answer":"区といたしましては、保護者の方が保育、教育というものを選択できるような環境の整備というものが必要だと考えていますので、引き続き幼児教育の質の向上を図れるように支援をしてまいりたいと考えております。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問","question":"やはり独立性、自主独立の精神に基づいて、建学の精神をしっかり発揮していただくような幼稚園経営に向けて、対応していただくべきではないのかなとも思っているのです。その辺の出し方も、それぞれの園の規模だとか、経営方針だとか、建学の精神をどうするか、そういったこともしっかり踏まえた中で補助の在り方を考えるべきだと思いますが、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"現在区のほうで私立幼稚園にお支払いしている補助金の考え方ですが、区全体といたしまして、保育教育、幼児教育の充実を図るために、一律の対応をしています。そのため、法人の経営種別による区分等々については考えてございません。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"今後どうなるかということは何とも予測がつきませんけれども、やはりそれぞれの経営母体の下で運営されている幼稚園が、果たして今後持続可能的に幼稚園運営をしていただけるかどうかということは、ある一定の保険をかけるというか、何というのでしょうか、危機管理ということも含めて考えたときに、今後持続可能な幼児教育を区で行うに当たって。","respondent":"芝野保育入園調整課長","answer":"公立、私立を合わせた今後の幼稚園の在り方ですが、既に在り方検討のほうで方針を詰めしています。","id":"exchange-110"},{"speaker":"田中委員","kind":"意見","question":"ある意味、延命のために補助金を出すということも１つの考え方としてありますが、一方で建学の精神や自主独立の視点から、やはり経営は自主的に努力してもらわないと困る部分も私はあると考えていますので、その辺のバランスをぜひ取った上での運営をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど、午前中ひがし委員からのご質問の中で、この出石つばさの家については支援区分６の方も取ってくださっているということでしたが、男女比などは、ごめんなさい、もともと男性に限りますとか、女性に限りますとかという条件がついていたか、私きちんと把握していなくて、その辺についてどうなっているか、まず伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"今後開設予定の区の整備案件としまして、小山七丁目、戸越四丁目のグループホームにつきましても、男女ともに受け入れる予定ということで、現在事業者と調整しています。","id":"exchange-112"},{"speaker":"吉田委員","kind":"意見","question":"これ事業者が頑張ってくださっているのだと思うのですけれども、男女それぞれとなると、ユニットのつくりとか、男女をきちんと分けなければいけないとか、それから支援員がそれぞれ、男性、女性両方ついていただかなければいけないとか、いろいろ厳しい条件がつくと思うのですが、その辺については事業者との話合いというか、要は区から何か支援が入るなど。","respondent":"佐藤障害者施策推進課長","answer":"こういった部分につきましては、介助支援する職員の体制として、女性の方を男性が介助するということはなかなか難しい状況がありますが、同性介助であったり、事業者の区への開設相談等の機会を捉えまして、区全体の状況を踏まえた配慮というものを。","id":"exchange-113"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。その辺についてもしっかり、そこは事業者と話し合いながら、適切な施設にしていただきたいと思います。大変な調査が出てきていて、これしっかり分析してから質問に使おうと思っていたのですけれども、ちょっと１点だけ、重度のグループホームの、支援区分５・６の方が入っておられるグループホームの数が、やはり他区に比べてとても少ないということが分かりました。","respondent":"佐藤障害者施策推進課長","answer":"民設のところに関しましても、先ほど運営費補助のところのご質問もいただいておりますが、障害者支援課と連携しながら、既存のところ、もしくは民設民営のところの施設につきましても、重度の方の受入れをできるような形の施策を検討してまいりたいと思います。","id":"exchange-114"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。それを求めまして、この質問は終わります。もし何か後で見解があったら伺います。これも今までの一般質問で、子どもの権利擁護を基にした児童相談所にしていただきたいということで、残念ながら子どもの権利条例はできなかったのですけれども、その理念はしっかり取り入れるということは確認をしております。そのことで、アドボケイトの仕組みづくりをずっと求めてまいりました。","respondent":"金子一時保護担当課長","answer":"運営の仕方についても、基本的には各子どものユニットに複数の職員に入っていただき、子どもと一緒に遊びながら、子どもの声を聴きながら、どのような形でこれから進めていくか、それこそ個別の面接をやるのか、集団の遊びの中で声を聴いていくのか。","id":"exchange-115"},{"speaker":"吉田委員","kind":"提案","question":"これまでも再三繰り返してまいりましたので、重々ご承知と思いますけれども、アドボケイトというものは、子どもの言葉を引き出すということが少し間違えると誘導するということにつながってしまうという、その辺の難しさは、私も全然専門性はありませんので、こうしなさいという提案はないのですが、その辺の話合いの状況などもあったら教えてください。","respondent":"金子一時保護担当課長","answer":"言葉で実際に言ったからといって、それは、例えば大人の顔を見て、子ども本人の自らの意向ではなくて、相手の気持ちを察して逆に言ってしまうお子さんもいらっしゃるので、そこは本当に様々な観点から、子どもの言った表現を。","id":"exchange-116"},{"speaker":"吉田委員","kind":"提案","question":"これ、今お答えいただいたことを、では現実にどうやって進めていくかということについても、私たちもしっかり見させていただきたいですし、これからもできる提案はしていきたいと考えています。これは要望です。だから子どもが相談に行っていい場所なのだということの周知が、学校などできちんと伝わっているのか、どのような形で伝えられているのか、その辺について、現時点での進捗を教えてください。","respondent":"長谷川児童相談課長","answer":"そのカードをお子さんが常に持っていて、何かあったら電話をする、相談すると。そのような機関があるのだということをお子さん自身に理解をしてもらう、そのようなフェーズに入っているのかなと考えています。","id":"exchange-117"},{"speaker":"吉田委員","kind":"確認","question":"そのようなことを考えておられるということを確認してよかったなと思いますが、それが今、もう既に開設されているのですけれども、これから配られるということなのでしょうか。その辺のスケジュールを教えてください。","respondent":"長谷川児童相談課長","answer":"今月中に配布できるように準備しているところです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"それは学校を通してなど、そのような形になるのでしょうか。それぞれの対象児童のいるところに直接配られる形なのか、その辺についても教えてください。","respondent":"長谷川児童相談課長","answer":"周知カードの配布方法になりますけれども、各学校に依頼文を送りまして、その依頼文と一緒に保護者宛ての通知文も送ります。その保護者宛ての通知文と通知カードをセットにして、各担任からお子さんに配ってもらうということを考えています。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。理解できないということなのかもしれませんけれども、子どもたちがどう受け止めるかはともかくとして、大人としては、きちんとあなたたちには子どもの権利としてこのようなものがあるのだということを少しずつ、何らかの形で伝えていくべきだと思うのですが、その辺について検討されていることがあったら伺います。","respondent":"長谷川児童相談課長","answer":"先ほどの通知カードに関連してなのですけれども、当然字が読めないお子さんにはちょっと配るのは難しいかなというところで、今回は小学校１年生以上を対象にしたカードを配らせていただきます。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ配慮されていることが確認できてとてもよかったと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"５０３ページ、介護保険の地域包括支援センター等では、地域包括支援センターと在宅介護支援センターの在り方を一般質問でも伺いました。こういったものが、生活支援サービスが日常生活圏域、品川ですと１３地域ですか、適切に提供できる体制が制度の根本というように、私は認識をしています。これまで地域包括支援センターと在宅介護支援センター、これを品川区方式というのでしょうか。","respondent":"菅野高齢者福祉課長、樫村高齢者地域支援課長","answer":"現在は、主には介護保険制度推進委員会の色合いが強く、こちらについては介護予防のことについてなど、そういった部分をお諮りするという形になるのですけれども、今後より一層、地域包括支援センターの在り方を検討する場としては。今回５０歳以上の方ということで、対象を広く実施したところですけれども、６５歳以下の受診率につきましては２５％ということで、想定よりもすごく多くの方、６５歳以下の方にご受診をいただいたというように区として認識をしています。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"２点目の補聴器のほうは、少し私聞き方がまずかったですかね。そこに区として介入して、いわゆる正しい補聴器の在り方とか、そこから認知症予防に確かにこれは大事だねとか、フレイル対策に大事だねと、そのようなところの検証を、事前の議論でも何回かやらせていただいたので、そのような意味でのご答弁をもう１回お聞きしたいと思います。これは要望で終わります。","respondent":"樫村高齢者地域支援課長","answer":"失礼いたしました。補聴器の件です。現在助成をした後、区としては、そこに個別に介入していないところではありますけれども、それぞれ個々に応じて、医師の方、それから販売店とつながりを持っているというように認識をしています。","id":"exchange-123"},{"speaker":"若林委員","kind":"意見","question":"そこで、要するに何台売ったということが成果ではないですよねと冒頭で申し上げました。そこからの成果をしっかりと、その後の生活の質のＱＯＬの向上のために、品川区は一定の対応、何か介入をということで、また改めてやります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"西本委員","kind":"確認","question":"２５７ページのすまいるスクール運営費にお伺いします。仕出し弁当の件です。目的は何でしょうか。改めてお聞きします。今年の夏休みにやりましたよね。各学校ごとに必要ないので、その人数と割合を教えてください。この配膳のために、新たに何人か人を配置したと思いますが、それに対する経費が幾らかかったのかということ、それから、アレルギー対策にはどのような指示を出したのかを確認したいと思います。","respondent":"藤村子ども育成課長","answer":"何点かすまいるスクールについてご質問いただきました。目的ですが、夏季休業中の仕出し弁当の提供というものは、昼食の選択肢を増やすというところを第１に、保護者の負担軽減というところを考えて実施しているものです。","id":"exchange-125"},{"speaker":"西本委員","kind":"確認","question":"大体２０％ぐらいの方が利用されたということなのですけれども、このアレルギー対策について、各校に１人、配膳等々で配置した方々全員にアレルギー対応のエピペンの使い方も含めて指導したということの理解でよろしいでしょうか。確認します。全員とは言いません。そこの、かなりちぐはぐ、何というのでしょうか、ずれが出てきてはいないでしょうかということが非常に気になりますが、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"アレルギーが入ったものを除いてくださいなど、そういったお話があったというところですが、保護者の方から、アレルギーがこういった形であるのですけれども頼めますかというようなご相談をいただいたようですが、今回。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"そのようなことを保護者の方々はどれくらい知っているのだろうかなと、私は非常に疑問に思います。やはりそのようなことをきちんとお知らせしなければいけないのではないでしょうかということが１点です。サポートするべきところはサポートしていいと思うのです。ですから、この考え方、お弁当１つとっても、やはり子育て支援というものはどうあるべきなのかということを、ぜひお言葉いただきたいと思います。","respondent":"藤村子ども育成課長","answer":"アレルギーに気をつけているという、担当職員のほうが保護者の方にお知らせしているかどうかというところですが、こちらのお弁当の実施に当たっても、アレルギーに大変注意しているので、お弁当のご注文をされる際はご注意くださいということで。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。２７５ページ、病児保育、時間があったら２３７ページ、心身障害者福祉会館運営費についてお伺いをいたします。初めに２７５ページ、病児保育について、現状についてお尋ねをします。この事務費の計上について、現在、品川区は区としてどのような対応をされているのでしょうか。よろしくお願いします。","respondent":"中島保育施設運営課長","answer":"各病児保育施設とも意見交換をしているところではありますが、委員おっしゃるとおり、課題というものを感じているところです。来年度予算に検討する上で、その辺のところのご意見等々も含めまして、ただいま検討を進めているところです。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問","question":"病児保育事業拡大のためには、現在病児保育を行っている各施設への支援の充実が必要と考えられます。ぜひよろしくお願いをいたします。今課長おっしゃられたように、前は４か所あって、今１閉室になっております。それも含めて、今後拡大が私は急務だと考えておりますけれども、区のお考えはいかがでしょうか。","respondent":"中島保育施設運営課長","answer":"病児保育施設につきましては、ここ数年数が減りまして、地域に偏りが出ているところです。その解消に向けて、解消がまず最優先と考えて取り組んでいるところです。それに向けて、今努力を進めているところです。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それと医療機関併設型の拡大に向けては、現在区から医療機関についていろいろ働きかけをしていると思うのですけれども、実際どのように行われているのかと、その働きかけの実際とその取組について、これまでの取組についてのご報告をお願いいたします。","respondent":"中島保育施設運営課長","answer":"具体的には、先月９月２５日に募集説明会を行いまして、４施設の医療機関にご参加いただいたところです。この周知に当たりましては、品川区医師会・荏原医師会にご協力いただきまして、会員の医療機関に周知をいただいたところです。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今４施設の申込みがあったということなのですけれども、今後、いろいろこれから検討段階に入ると思うのですが、実際、この先どのぐらいの期間を見据えて決定をなされるのかどうかということを確認をさせてください。お分かりになっている範囲で、今現時点のことをお尋ねします。","respondent":"中島保育施設運営課長","answer":"ただ、保育士の確保や、施設の様々な条件ありますので、そこは各医療機関の実情等も確認しながら進めてまいりたいと思います。期間については、ちょっとまだ明確には申し上げられないのですが、できるだけ早く、可能な限り早く進めてまいりたいと考えています。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それを含めて、当然検討されていると思うのですけれども、具体的にこの辺だよという、何か地域のこの辺を想定しているのだという、大体候補地この辺ですよということがもしお分かりになれば教えていただきたいと思います。","respondent":"中島保育施設運営課長","answer":"つきまして、やはり海側、東側のエリア、できれば大井町がまずは拠点となるのでいいのかなとは思うのですが、そのようなところを中心に、幅広い形でご利用いただけるような場所について進めていきたいと考えています。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"提案","question":"本当に我が会派からも以前から提案しています、医療的ケア児も預かることができるような病院が行う中核的病児保育施設のこともありますので、このネットワークの構築をぜひよろしくお願いいたします。以前質問をさせていただいた、失語症向け意思疎通支援者というものがあるのですけれども、今現在検討をされているのか否か、この先どのような方向性でいるのかどうか、教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"それとともに、先行区の状況を調査しています。今後に向けて、具体的にその先行区の状況を調査しまして、検討してまいりたいと考えています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"意見","question":"よろしくお願いします。２４１ページの障害者支援事務費、２５５ページ、児童センター運営費、そして２６９ページ、特別支援保育、２７９ページ等の特別支援巡回相談についてです。就学前の特別支援の保育についてお尋ねします。そこで、決算書も予算書もそうなのですが、特別支援保育という項目と特別支援巡回相談という表現が２つあるのですけれども、その表現の違いがどのような形であるのかお尋ねします。","respondent":"中島保育施設運営課長","answer":"こちらにつきましては、特別支援保育といいます、医療的ケア児で看護師を派遣している費用と、あとまた、今委員おっしゃられましたとおり、巡回相談、育児相談、また審査会など、それぞれ所要の経費のほうを特別支援保育というところで計上しています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"特別支援保育というものは巡回相談だけでなく、今お話にあったような事業も行っていると認識しました。その巡回相談についてお尋ねするのですが、巡回している臨床発達心理士、学校心理士たちと区の契約はどのような形になっているのでしょうか。報償費をお支払いしています。１時間で１万２,０００円と伺っています。","respondent":"中島保育施設運営課長","answer":"今委員おっしゃるとおり、報償費でお支払いをしています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"どのような契約の形態で、この心理士の方たちと契約を行っているのでしょうか。委嘱とか、委任とか、いろいろあると思うのですが。","respondent":"中島保育施設運営課長","answer":"契約の形態はちょっとすみません、恐らく委嘱ではないかと思いますが、すみません。少し曖昧です。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"意見","question":"恐らくということですが、例えば委嘱だとすると、委嘱状をお渡ししているのか、あるいは口頭で契約をしているのか、それとも文書で心理士たちと契約をしているのか、どのような位置づけで契約をされているのかということをお尋ねしたのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、どうなのでしょう。それで次に、この事業の基本的な事項、例えばどこを回るだとか、どのようなことをするだとか、そのような目的や細々としたことを定めているものがあるのでしょうか。例えば実施要綱などです。例規集を拝見したのですが、私ちょっと見つけられなかったので。","respondent":"中島保育施設運営課長","answer":"こちら巡回相談等に関する内容ですが、特別支援保育の手引きというものを保育施設運営課で作成しておりまして、そこに目的等、体制等は定めているところです。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、手引であるということでは、要綱がないということになると思います。そうすると、この事業に関する意思決定、つまり心理士にお願いすることは、その手引ではお願いできないわけですよね。要綱で定めて、心理士にお願いするわけです。要綱がないとすると、１件１件それぞれ、１件決定というのですか、毎年毎年どのように、この事業を心理士にお願いしますと決定しているのでしょうか。","respondent":"中島保育施設運営課長","answer":"毎年度、１件決定という形でしていると思います。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"要綱のお話をしているのです。この制度が、もうここまで整備されたことは私は、大変すばらしいと思っているのです。制度として事業をきちんとしたものにするには、根拠として意思決定のよりどころになる要綱で、文書としてきちんと決めておく必要があると思うのです。それで指導のラインを決めておかなければいけないと。それをつくる必要があると思うのですが、いかがでしょうか。よろしくお願いします。","respondent":"中島保育施設運営課長","answer":"こちらの巡回相談、特別支援保育につきましては、ノウハウも長らくやっておりまして積み上がってきておりますので、要綱の作成については検討してまいりたいと考えています。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"検討するということで、ぜひお願いします。その意味でも要綱は、検討と言われましたけれども、必ず決めていただいて、そして心理士の方たちに示して、さらにこの事業を進めていっていただきたいと思います。ちょっと素人の考えだと、要綱がないと、何でしょうか、突然こういった事業が打ち切られる可能性もあるのではないかと心配してしまうのですけれども、それは杞憂なのでしょうか。","respondent":"中島保育施設運営課長","answer":"この事業自体はとても必要性の高いものですので、継続的にやっていきたいと思っているところです。ちょっとその形というか、事業継続性を示すようなものにつきましては、今後検討してまいりたいと考えています。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"いいと思っていらっしゃるので大変ありがたいのですが、続けていきたいと思っているという確実なものとして、私は要綱が必要だと思っています。幾つかそのほかの事業も行っていきたいと思います。例えば相談会や、先ほど幾つかあった研修会など、そのようなものも、私立の保育園と区のほうが保育委任しているわけですから、拡大してもらいたいと思うのですが、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"私立保育園における特別支援児の対応ですが、現在におきましても、特別な支援が必要なお子様の加配に関して、人件費の補助などをしておりまして、充実した保育内容とする必要があると考えています。","id":"exchange-142","title":"議員研修会の内容と所要時間"},{"speaker":"高橋（し）委員","kind":"質問","question":"私立のほうも公立のように充実したものにしていくというお話ですから、お願いしたいと思います。そして、学校心理士の訪問も数を拡大してきていただいたわけです。ですから、さらにそれを、臨床心理士は１０５行っているのですが、学校心理士のほうは９０なので、臨床心理士のほうに合わせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"私からは、２８７ページ、生活保護経費について伺います。今回の決算で、生活保護システム改修等経費として、約１,４５２万円と少し多めの金額が計上されているかと思います。システム改修の中身についてお願いいたします。","respondent":"豊嶋生活福祉課長","answer":"１つはオンライン資格確認と申しまして、マイナ保険証絡みのシステム改修、これが１つ、６６０万円ほど、そしてもう一つ大きかったものが、昨年度、５年に一度の生活保護の基準改定がございまして、その基準改定に伴うシステム改修、こちらが４６２万円で計上されてあります。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問・要望","question":"これ自体は、保護の補足性という生活保護法の趣旨からすれば、当然な返還を求めていくものだとは思うのですけれども、ただ不正受給の場合と異なって、やはりこの生活保護受給者の方たち、いろいろな方がいらっしゃいますので、配慮すべき点ということもあるのだと思います。そういった観点から、初日は６３条返還金と税金の関係を取り上げました。５年間たっているわけです。","respondent":"豊嶋生活福祉課長","answer":"ただ、税金になりますので、所管外というところもございまして、一つひとつ、その辺りは申請に基づいて、最終的には所管が判断するものとは考えてありますが、今のお話であれば、基本的には控除という考えで間違いないのではないかと考えております。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問","question":"このような回答をしていただいて、お調べいただいて厚く御礼申し上げます。ですから、ここの点について、なかなか本当にご多忙な部署なので大変だとは思うのですけれども、できればこういった年金の遡及受給のときにどのようになるのかというところを課の中で共有していただいて、丁寧に説明していただけないかなと思うのですが、いかがでしょうか。","respondent":"豊嶋生活福祉課長","answer":"そのご案内の基になるものが、保護開始時に２９条調査と申しまして、年金事務所等々に、その方に年金の受給権があるかどうかということを事前に確認しておりまして、その方が実際に６５歳になったときに生活保護を受給しているようであれば。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"今のところなのです。そういったことが、今回、私も質問させていただきながらすごく勉強になりました。先ほど他の委員、やなぎさわさんからもケースワーカーの増員というようなお話ありました。ですから、ぜひ、本当にご公務多忙だとは思うのですけれども、ちょっと時間を取って、生活保護課、窓口のほうで見ていただくということも１ついいのではないかなと思います。どうかよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問","question":"２５２ページの児童福祉費で、まず大きく伺います。子ども未来部長、前職企画課長で、人口動態については物すごく詳しかったと思うのですが、それを含めて、子どもの未来でどのような施策をして、どのようにしていきたいかということを、まず初めにお伺いします。","respondent":"佐藤子ども未来部長","answer":"企画では人口動向や公有地活用等に加えまして、横断的な調整に取り組みました。これらのノウハウは、現在策定しておりますこども計画の検討の中で、保育の需要・供給や、老朽化施設の改築計画等に活かしてまいりたいと考えております。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"先ほどまで席がなかったようなのですがその席に座られて、第３庁舎も部長中心に子どもの席があるのに、担当課長の席はないですよね。「何でないの」と言ったら、「あちらのリボンのところに行っています」と言われたのですけれども、課長、せっかくこの場に出てきてくださったのだから、自分はこの課の担当課長としてこのようにやっていきたいのだという思い、その辺をぜひ教えていただけますか。","respondent":"柴田子ども施策連携担当課長","answer":"私はまだ駆け出しではありますが、部内の各課の施策をしっかりと見据え、また、子ども計画の担当もしていますので、そういった観点からも、幅広く子ども施策というものを見て、進める一助となりたいと考えておるところです。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"そして次が、福祉部のほうに行きますが、２３５ページ、福祉タクシー、介護タクシーなのですけれども、操車料、予約料、あと基本介助料、これ３点セット、ぜひ来年度の予算でしっかりつけていただきたいと思うのですけれども、いかがでしょうか。２４５ページ、荏原特別養護老人ホーム等大規模改修工事に関連してなのですけれども、これ所管といいますか、総合的に所管するのはどこでしょうか。区民の方に。","respondent":"松山障害者支援課長、東野福祉計画課長、菅野高齢者福祉課長、樫村高齢者地域支援課長、豊嶋生活福祉課長、佐藤障害者施策推進課長","answer":"利用料金が高額になる、ご負担が大きいというお声はいただいておりますので、今後しっかり検討していきたいと考えております。成り手不足という部分につきましては、第３回定例会の答弁でも述べましたとおり、区としては。現在建物のほうが２５年たって、大規模改修工事を実施しておりますが、荏原保健センターのほうが借移転先にその部分が移転して。そのため、当然職員の業務量というものも増加していくものというように見込んでおりますため、適切な区民サービスが行き渡るよう、また。","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問・要望","question":"特別養護老人ホームなのですけれども、荏原保健センター長が所管ということで、課長、前社会福祉協議会にいらっしゃったわけですから、いろいろな全体を見られるので、ぜひその辺安定した運営をしていっていただきたいと思います。そして次、しながわふれあいメッセージ集、今日読むことはやめようと思っています。今ちょうど赤から青と来たから、今度黄色だと思うのです。","respondent":"菅野高齢者福祉課長","answer":"こちら２か年度にわたって、この事業を実施してまいりました。","id":"exchange-151"},{"speaker":"藤原委員","kind":"質問・要望","question":"読まないと駄目ではないですか。これは私がここで質問する一番の、心なのです。台風も大雪の日も命がけですよね。なぜこのようなすばらしいことをやめてしまうのですか。だったら品川区がそれはいけない、違うでしょと発信していくべきだと私は思います。どのようにやったのですかなど、来ていますよね。そのような思いで今日質問させていただいたので、最後に森澤区長、一言いただければ幸いです。","respondent":"森澤区長","answer":"生活保護のケースワーカーもいろいろ、福祉の現場というものは本当に非常に大変だと思いますので、そういった現場の皆さんがしっかりと力を発揮して、区民の皆さんの幸せのためにしっかりと支えられるような環境整備に引き続き取り組んでいきたいと考えています。","id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、２３０ページの障害者支援費から、区役所の手話通訳者の配置についてと、障害者相談員への相談について伺いたいと思います。区では、令和３年の７月１５日に手話言語条例を制定し、手話は言語であると条例にも明記し、差別解消や理解促進へ様々対応されているところだと思います。本当によかったと思っているのですが、拡充した理由と、何人体制でやられているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"区役所だけではなく、区役所以外への派遣も行っておりますので、どれぐらいのめどで派遣できるかということで調整がついたのが今年度だったです。体制につきましては、それぞれ手話通訳者の方のご都合等もありますので、派遣可能な方を配置していただいている現状にあります。","id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区聴覚障害者協会の方々からも毎年のように寄せられていた要望でしたので、拡充されたことはよかったなと考えています。今回月曜から金曜まで要望があったからという理由でしたが、こうした合理的配慮という観点からも、５時までという検討はされたのでしょうか、伺います。課題等がもしあるなら伺いたいと思います。","respondent":"松山障害者支援課長","answer":"手話通訳者の配置時間の検討です。こちらにつきましても、心身障害者福祉会館の指定管理者を通じまして、手話通訳者の登録の会の方々とご相談させていただきながら、現実的にはどれぐらいの時間配置できるのか。","id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に様々忙しくなる中での、拡充というところで大変だったと思うのですけれども、手話通訳者、この登録者がさらに増えると、もう少し違ってくるのかなと思うのです。昨年手話通訳者の登録者数が２８人だったと思うのですけれども、現在はどれぐらいになっているのか伺います。","respondent":"松山障害者支援課長","answer":"手話通訳者の登録者人数についてです。現在も２８人です。","id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"しかし、この通訳だけでは生活が成り立たないという声もあります。そして昨年も、全国統一試験にしてほしいという声も紹介して、処遇改善も含めて求めました。何か２３区で初で試験実施しますというようなものが、平成３０年でしたか、それぐらいに出されていたと思うのですけれども、その遠隔通訳についてはあまり耳にしないのですが、そこの状況はどうなっているのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"遠隔手話通訳についてですが、こちらを実施に向けて検討していたのは、コロナのときに、手話通訳者の方々がなかなか医療機関に出向かうということが不安がかなり強いということで、遠隔ではできないだろうかということで、会館のほうにパソコンを単独で設置しまして。","id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"当事者からは、区役所への手話通訳はじめ、病院や警察、消防、介護施設などにも手話の普及をと求めています。早急な、さらなる対応が必要だと思うのですけれども、この合理的配慮をと、研修等もされながら手話通訳者も増やすというところ、姿勢は持っていただいているのですが、やはり国や都のさらなる積極的な支援も必要なのではないかなと思うのですけれども、区はその辺どのようにお考えでしょうか。","respondent":"松山障害者支援課長","answer":"東京都の派遣センターのほうから来ていただいている状況にありますので、恐らく国や都も、人材確保というものはそれぞれ努めているところだと認識をしております。","id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり全体で進めなければいけないのだなということは思うのですけれども、手話言語法をこの当事者の皆さん求めています。国会でも、今年の６月には、共産党を含む野党共同で、手話言語法案と情報コミュニケーション法案が共同提出されています。引き続き、手話言語通訳者の配置、最低限の合理的配慮として、庁舎が開いている時間の配置を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"大倉委員","kind":"質問","question":"ページ２７３ページ、保幼小ジョイント事業、ページ２３３ページ、障害者介護給付事務の同行援護について伺います。前回も質問させていただいたのですが、改めて、品川区が進めてきた先進的なこの事業について、今までの成果を教えてください。小１プロブレムの解消を目指して行っているというところでは、そうした解消に向けて、実際どのように課題解決ができているのかというところの検証も教えてください。","respondent":"中島保育施設運営課長、松山障害者支援課長","answer":"そのような課題解決にはまだまだ道半ばかなというところではありますが、引き続き学校と連携して進めてまいりたいと考えています。同行援護従事者養成研修を区が委託しまして、例年実施して継続しているところです。ただし、例えば令和４年度は１０人の方の応募があったのですが、令和５年度は８人ということで、少し減少傾向にあるというところです。","id":"exchange-159"},{"speaker":"大倉委員","kind":"質問・要望","question":"私が伺ったところだと、受けたけれども、特にその後働きかけがなかったというようなお話があったと聞いておりますので、その辺しっかり働きかけて、少しでも増やしていっていただきたいなというところでお願いします。もしくはそういったアプリが使えるような日常生活給付事業の追加の検討などもできるかなと思うのですが、そうした検討についてお話を伺わせていただければと思います。","respondent":"中島保育施設運営課長、松山障害者支援課長","answer":"こちらからも学校に引き続き、毎年お願いしていますので、これからも一層連携を図って、１人でも多くの園児を交流できるようにしてまいりたいと考えています。今、様々なアプリが確かに開発されておりまして、新たな視覚支援用具が日々開発されていることから、今後も当事者の方のご意見を伺いながら、日常生活用具検討会等で。","id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"保幼小の連携のほう、学校の側も１園しか受けていないところがあったり、３園とか、４園とか、うまく受けてもらっているところがあったりするので、その辺聞き取っていただきたいと思います。ガイドヘルパーのほう、当事者の声を聴きながら検討ということでぜひ進めていっていただきたいと思います。","respondent":"松山障害者支援課長","answer":"スマホ等の活用については、引き続きまた検討会等で検討してまいります。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２６７ページ、子どもの未来応援事業、子ども食堂開設・運営支援、フードパントリー事業支援、しあわせ食卓事業から子どもの食について、２３５ページ、日常生活用具給付事業、２２５ページ、高齢者安否確認事業、救急代理通報システムについて伺ってまいります。１点目は今年度の結果やご意見を踏まえて、来年度もぜひ拡充をした上で継続をしていただきたいと思いますが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"今後のことにつきましては、今回の支援の効果など見極めながら、来年度の施策については検討してまいりたいと考えております。周知についてです。今回この周知について行き届かなかった点があったことについては、認識、十分しています。","id":"exchange-162"},{"speaker":"あくつ委員","kind":"質問","question":"品川区が把握している人工呼吸器の必要な医療的ケア児、医療的ケア者の人数を教えてください。医療的ケアが必要なご家庭のこのような不安に対して、品川区は令和４年度から、日常生活用具給付事業のメニューの中に、在宅人工呼吸器の利用者への自家発電機および蓄電池バッテリーの給付を開始し、災害時の電源確保を支援しています。令和５年度の支給件数をそれぞれ教えてください。","respondent":"松山障害者支援課長","answer":"人工呼吸器者の人数です。昨年１２月時点で２５人です。それから蓄電池、それから非常用電源の実績です。令和５年度は合計で９件です。","id":"exchange-163"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その前提として、医療的ケア患者にご参加いただいての実証実験、訓練を行ってはいかがでしょうか。そして、区内避難所ごとなど数か所に移動できる電源として、そうした電気自動車を、またプラグインハイブリッド車を派遣して、その場所については、医療的ケアの必要な当事者、ご家庭へマップと併せて周知をしていただきたい、こうしたご要望だったのでそのままお伝えをしますけれども、ご所見を伺います。","respondent":"松山障害者支援課長","answer":"やはり災害時には停電が長期に及ぶ可能性もあるということを考えますと、今の自家発電装置だけでは数時間しかもちませんので、別な方法、川崎市の事業を今後調査いたしまして、電源確保の可能性や包括協定との連携と、あと区有車の利用等々。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"よろしくお願いします。そうしましたら、救急代理通報システムについて伺ってまいります。その際に、団体からは、次のような評価がありました。第２回定例会における公明党の一般質問の中で、家賃滞納や残置物処理に対する大家の懸念を払拭するために、セーフティネット住宅等への保険料助成も含めた保険制度の導入、これを求めましたところ、検討していくという、このようなご答弁もいただきました。","respondent":"豊嶋生活福祉課長","answer":"身元が分かっていて引取り手がない方、墓地、埋葬等に関する法律によって、区として対応した件数ですが、昨年度６２件あります。これは生活福祉課の中の生活保護の受給者の方は入ってございませんので、若い方も含まれている件数です。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"提案","question":"品川区も含め、全国的にそういった傾向であると。このようなことに関しまして、終活情報登録ということを今行う自治体があります。先ほど述べました横須賀市、また、豊島区でも同様のものを行っています。１１項目、横須賀市では行っています。こうした中で、こうした登録情報制度の導入、そして、ぜひこれは無料でやっていただきたいということを提案いたしますけれども、ご所見を伺います。","respondent":"東野福祉計画課長","answer":"先ほどの重要書類のお預かり、５００円ですが、区としては、無償化というところでも一定程度考えていきたいと考えています。","id":"exchange-166"},{"speaker":"まつざわ委員","kind":"確認","question":"私からは、成果報告書の３５ページ、認知症高齢者支援事業と、決算書２４７ページの認知症理解促進事業について質問いたします。は認知症高齢者事業の中で、例えばサポーターの在り方、検診事業についての状況をまず確認させてください。","respondent":"樫村高齢者地域支援課長","answer":"認知症検診事業の状況ですけれども、令和４年度に開始した事業でございまして、当初の実施医療機関は１５機関でございましたが、昨年度は倍の３０機関、それから今年度については４０機関に、協力いただける機関が増加いたしまして、また、令和５年度の検診率につきましても。","id":"exchange-167"},{"speaker":"まつざわ委員","kind":"質問","question":"特に検診に関しては、１５から３０、３０から４０とどんどん拡充している。団塊のジュニア世代、これが６５歳以上になる２０４０年には認知症の高齢者が５８４万人に上るという推計を、厚生労働省の研究班がまとめています。区ではこの課題にどう向き合っているのか、まずは教えてください。こういった品川区ではありますけれども、企業との連携、そしてまた拠点の考え方について、ご見解をお聞かせください。","respondent":"樫村高齢者地域支援課長","answer":"それから拠点についての考え方ですけれども、こちら委員ご指摘のとおり、現在区のほうでは、拠点を決めずに各事業を実施しています。今後につきましては、他自治体の情報も収集しながら、進め方について検討してまいりたいと考えています。","id":"exchange-168"},{"speaker":"まつざわ委員","kind":"質問","question":"企画会議の中からオレンジフェスタが生まれたということは、品川区が誇るサポーターの活用の中ですばらしいステップアップだと思っていますので、さらなる拡充を期待しています。でも実際にチームを立ち上げて活動している自治体というものは、全国３３９自治体と、全体の２割にも満たないことが現状でありますが、現在品川区の現状を教えてください。","respondent":"樫村高齢者地域支援課長","answer":"今後につきましては、先行自治体などの情報も参考にしながら、品川区独自のチームオレンジ化というものを目指して、課一丸となって取り組んでまいりたいと考えています。","id":"exchange-169"},{"speaker":"まつざわ委員","kind":"提案","question":"行政や専門職がその力を借りていく、そういったスタイルで、認知症の人とサポーターの人のそれぞれの要望がうまくマッチングしていければと考えています。次に、認知症理解促進事業の中で、先ほどオレンジガイドの話が出ましたけれども、これ私二、三年前から、しながわオレンジガイドの見直しというものを提案させていただきましたが、昨年度からいよいよ改訂に向けて動き始めたと答弁をいただいています。","respondent":"樫村高齢者地域支援課長","answer":"なお名称も、これまで使用しておりました品川“くるみ”認知症ガイドから、しながわオレンジガイドに名称を変更いたしました。より多くの方に手にしていただけるよう、周知啓発を積極的に行ってまいりたいと考えています。","id":"exchange-170"},{"speaker":"まつざわ委員","kind":"確認","question":"改訂したことの確認が取れました。その改訂の中で、工夫した点、また参考にした自治体、あったら教えてください。","respondent":"樫村高齢者地域支援課長","answer":"オレンジガイドの改訂ですけれども、こちらは認知症基本法の成立、施行など、それから認知症の人や家族を取り巻く状況が変化いたしまして、冊子の内容へのニーズが変化したことを受けて実施したところです。","id":"exchange-171"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そうしたら、やはり非常に見やすくて分かりやすいと。本当に私もうれしいぐらい好評だったので、これ私の勝手な感覚なのですが、このような状況を踏まえて、本当にいいものができたので、例えばもう増刷してしまうとか、例えば配布先、周知の方法というものを、どうしてもいいものというのはよく宣伝していただきたいので、そういった配布先や周知の方法、そこの考え方を教えてください。","respondent":"樫村高齢者地域支援課長","answer":"ちょうど今週に１万部が納品されるような予定になっております。それから配布先については、地域センターなどの福利施設をはじめとしまして、医師会や薬剤師会、介護事業所、認知症カフェ、一部の民間企業にもご協力をいただき、配布に努めているところです。","id":"exchange-172"},{"speaker":"まつざわ委員","kind":"質問","question":"ですから、やはり一度進み続けた事業、この事業というものは、進んだことを大変に評価しているのですけれども、大きく進み続けた事業は、まとまりにくくなっていくので、しっかりまとめ一旦整理して、更に大きくまとめていくことが、職員の皆さんの負担軽減、また新たな視点での課題解決の方法を見つける一助になると思いますので、そういった部分で、事業の整理に関してご見解をお聞かせください。","respondent":"樫村高齢者地域支援課長","answer":"これからの展開ですけれども、今まで進めてきた新規事業を進めるだけでなく、現在行っているこの既存事業につきましても、区民の声や専門家の方のご意見というものをしっかりと踏まえまして、進めるだけでなくて、見直しや内容の充実というものをしっかり図って。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6853#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":120484,"voices":394}},{"id":"r06-20241008-4","meetingId":"r06-c-settlement","date":"2024年10月8日","dateIso":"2024-10-08","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時４１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を164件抜き出しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯新妻委員長 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯新妻委員長 ただいまより、決算特別委員会を開きます。 それでは、令和５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"本日も１日、どうぞよろしくお願いいたします。私からは、３３１ページのホリデー・トレーニング事業助成、３２９ページ、省エネルギー対策設備更新助成金についてお伺いいたします。コロナ禍の期間の商店街のイベントに対する東京都や品川区の支援内容を改めてご説明いただくのと併せて、一番落ち込んだ令和２年度と前年度、令和５年度との比較を教えてください。","respondent":"小林地域産業振興課長","answer":"こちらにつきましては、東京都が３分の１、区が３分の１、商店街が３分の１ということで、これは１００万円以上のイベントになるのですけれども、１商店街当たり上限３００万円という支援制度があります。","id":"exchange-001"},{"speaker":"えのした委員","kind":"質問","question":"令和５年度は３１件まで戻ったということで、本当に商店街のイベントの数が戻ってきたことはよいことだと考えております。森澤区長にもお越しいただいて、地元の人気料理人の笠原将弘シェフにもご協力いただいた、武蔵小山のたけのこ祭りや、大井どんたく、あと先日、私も、しながわ宿場まつりにお伺いいたしました。地域ににぎわいが戻ってきたことを実感しているところであります。","respondent":"小林地域産業振興課長","answer":"商店街の中で、次世代の担い手の方たちがこういったイベントを自主的にいろいろ企画実施するということを通じまして、商店街活動の活性化ということを狙いとしている事業です。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問","question":"ご近所の身近な買物先として、ふだんから区民の皆さんとの接点が多い商店街の特徴を活かした、地域の中での新しい役割も期待できるのではないでしょうか。従来のイベント支援やホリデー・トレーニング支援などに加え、商店街の新しい役割に即した区からの支援も進むと、地域にとって非常にプラスになると考えますが、区としてのご見解をお伺いいたします。","respondent":"小林地域産業振興課長","answer":"こうした新しい活動が進むことを区としても評価しておりまして、こういったところも含めて、今後、商店街の新しい役割に、区が何か支援できないかということを考えてまいりたいと思います。","id":"exchange-003"},{"speaker":"えのした委員","kind":"提案","question":"内閣総理大臣表彰、大変すばらしいと思います。こうした新しい活動が進むことを、区としても評価していただいて、ぜひ今後とも支援の拡充をよろしくお願いしたいと思います。商店街、特に飲食店の皆さんは、電気代の上昇は経営に直結する問題です。区ではこうした事態を踏まえ、９月の議会に物価高騰対策の補正予算案を提案されていますが、その内容と狙いをお伺いいたします。","respondent":"小林地域産業振興課長","answer":"今回、補正予算の中で提案している助成金につきましては、企業の業務改善・業務効率化も狙いとしておりまして、例えば新紙幣の対応券売機も本助成金の対象とする予定としております。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"先日、ラーメン屋にお伺いしたときに、私は新紙幣しかなくて券売機が使えずに、お店の方に両替をしていただきました。お話を伺ったところ、両替をするのは毎朝のことで、銀行への両替業務も大変だということでした。物価高騰はまだまだ当面続くと見られておりますが、補正予算などを通して、引き続き機動的な柔軟な区の支援をお願いして、私からの質問を終了します。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３０９ページの猫の不妊・去勢手術費助成、また２９７ページのＡＥＤ管理費から、それぞれお伺いしたいと思います。初めに、猫の不妊・去勢手術費助成についてお伺いします。品川区地域猫活動協力チームの実績について教えてください。","respondent":"赤木生活衛生課長","answer":"委員からご質問いただきました地域猫活動のうち、協力員に関する実績ですけれども、今、現状としまして、申請していただいているチームとしましては、１チームになります。そのほか、２件ほど、今、協力員として活動できないかどうかについて相談を受けているところです。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"１件のチームと、今、２件が見えているということで、事業開始から約半年ということで、区民への浸透がまだ十分ではないかと思いますが、こちらについての分析と、今後の展開についてお聞きできればと思います。","respondent":"赤木生活衛生課長","answer":"協力員チーム制度の周知に関するご質問かと思います。こちらの周知につきましては、本年の６月に全町会長宛てに、事業の概要を記した文書を送付するとともに、希望がございました町会長に個別にご説明をさせていただきに、町会長会議にお伺いしています。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"不妊・去勢手術は、現金で動物病院に支払い、申請後の約１か月半後に支給となりますが、現場では一匹、二匹の話ではないため、改善を求める声が上がっています。品川区では捕獲してから３０日以内の申請となっていますが、捕獲と並行しながらリリースする猫や、治療後に譲渡できる猫１０匹前後で行っていると、手続が短いとの現場の声があり、せめて６０日の申請にはできないでしょうかというお話もあります。","respondent":"赤木生活衛生課長","answer":"今後の在り方につきましてですけれども、他自治体の動向も含めまして、在り方については引き続き検討してまいりたいと考えています。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"もろもろ検討していただければと思います。ボランティアの高齢化もあり、この中核の方からも、体力的にも今回で活動を最後にすると聞いています。現在、猫の繁殖が、ボランティアや区の周知により、ここまで抑えられていますが、さらなる対策が必要であると思われますが、こちらについて改めてお聞きできればと思います。","respondent":"赤木生活衛生課長","answer":"こちらにつきましては、新たな担い手の発掘を目的としまして、猫の講習会というところで、来月、１１月にまず実施しますけれども、そういった講習会を通じまして、新たな地域猫活動の担い手を発掘させていただきつつ。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"問題は、来年の３月妊娠が一斉に出産となる４月が、このままの状態となると、１つの町会だけではなく、周辺の町会にもまたがって倍増していくと伺っています。異常な事態になっている際、保健所が介入しての指導、または、町会と無責任な餌やりをされている方との話合いができるように、保健所が橋渡し役となっていく必要があると思われますが、改めて区の見解をお聞きしたいと思います。","respondent":"赤木生活衛生課長","answer":"そういった中で、不適切な、例えばですけれども置き餌、餌を置きっ放しにしている状況ということになりますと、猫だけではなくて、その他の害虫の発生や、公衆衛生のところに危害を及ぼす可能性もありますので、そういったところを含めまして。","id":"exchange-010"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、３２３ページのＩＴスタートアップ支援事業、３２７ページの雇用確保支援事業、３２９ページの外国人材受入・定着支援事業、商店街活性化事業費、３３１ページの共通商品券普及促進事業について伺います。商店街活性化事業費に関連し、この６月に行われた総額５億円のキャッシュレス決済ポイント還元事業について伺います。","respondent":"小林地域産業振興課長","answer":"こちらは、各ペイメント会社で本人確認がどこまでできているかという部分ですけれども、現在、我々が把握しているところでは、これは前回実施したキャッシュレス事業と、データとしてはほぼ同じなのですが、ａｕＰＡＹ、楽天ペイが、区民割合が約４割、ｄ払いが約５割です。","id":"exchange-011"},{"speaker":"山本委員","kind":"確認","question":"区民利用が４割から５割ということで理解いたしました。本事業の目的が、区内経済の活性化と区民のための物価高対策の両方であるとすると、やはり多くの区民の方に利用していただいたほうがよいと考えます。利用者アンケートや満足度確認の実施の有無、区としての評価、今後の実施予定についてお教えください。","respondent":"小林地域産業振興課長","answer":"今後、課題として我々が考えているのは、前回６,０００店舗で、令和６年度６月は８,０００店舗に近いような店舗数でやっておりましたけれども、こちらについて、さらなるキャッシュレスの利用拡大という点からは、店舗の拡大がさらに進むことが望ましいと認識しています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"もし次回、実施する際には、利用店舗の一覧を作成するなど、改善をお願いしたいと思います。後ほどの話につながりますが、デジタル商品券、デジタル地域通貨など、より有効で効果的な手段を検討していくことを引き続き要望します。次に、共通商品券普及促進事業について伺います。今年度、デジタル商品券に関する調査費用２４２万円が予算化されておりますが、現在の検討状況についてお聞かせください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今ご質問いただきましたデジタル商品券検討の進捗ですけれども、上半期につきましては、デジタル地域通貨およびデジタル商品券を実施している先行自治体の複数の事例を調査したところです。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"現在の検討状況について理解いたしました。この後ご質問する、東京都が進めるデジタル地域通貨Tokyo Tokyo Point（仮称）、略してＴＴＰと申し上げますが、このＴＴＰとの兼ね合いもありますので、なかなか見通しにくいところですが、区としてのデジタル商品券の導入に対する今後の見通しおよび、課題があればお教えください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今、委員からお話がありましたＴＴＰとの関係もあろうかと考えていますので、そういった課題を含めて検討していくところです。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"理解いたしました。導入に当たっては、今後の利用拡大の可能性を踏まえ、デジタル地域通貨への発展ができる仕様で選定を進めることを要望いたします。次に、ＴＴＰについて伺います。我々、しながわ未来は、今年７月に東京都に伺い、ＴＴＰについて勉強会を開催いただき、理解を深めてまいりました。このＴＴＰに関して、都からの説明状況および現在の区の検討状況についてお教えください。","respondent":"横田デジタル推進課長","answer":"本年７月に都主催の説明会があったほか、８月に都と品川区で意見交換を行いました。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれの基礎自治体の要望をどこまで組み込むことができるのか。どのような設計になるのかは現状ではまだ分かっていない状況ですが、区としてできることは、区の要望を都に前広に伝えた上で、今後の都の動向を見守ることと考えます。次に、ＩＴスタートアップ支援事業の中で、品川スタートアップ・エコシステムについて伺います。概要と目的、現在の企業の参加状況などについてお聞かせください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"目的につきましては主に３つ考えてございまして、１つは、将来雇用を創出するような、スケールする企業を増やしていくということと、２点目につきましては、スタートアップや女性、それから学生など、いろいろな方々が起業にチャレンジできる。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"とてもよい取組であると考えます。スタートアップ企業が大きく成長しても、区が税収で直接大きく潤うということではないですが、課長のおっしゃる効果も大きいと考えます。区の行政サービスの向上、業務効率化など、品川区に貢献する仕組みに関するコンテストを開催し、よければ実証実験で積極的に採用する仕組みをつくってはいかがでしょうか。区の考えを伺います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今年度につきましては、スタートアップ・エコシステムの参画者を獲得するということに注力していますけれども、庁内とも連携しまして、例えば品川区が実施するウェルビーイング・ＳＤＧｓ推進ファンドに、こういったスタートアップを紹介して応募していただいて。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問","question":"ぜひ庁内でも連携していただきつつ、この仕組みの中でも多くの区内企業を巻き込み、進めてほしいと思います。次に、雇用確保支援事業について伺います。１０月２日の日経新聞によれば、２０２１年４月に、企業が日本学生支援機構に直接返済する奨学金返済支援制度が新設されて、風向きが変わりつつあるとあります。奨学金のある社員の負担軽減。まさに三方よし。本制度の概要と利用実績をお教えください。","respondent":"小林地域産業振興課長","answer":"ただいまご指摘いただいた事業ですけれども、東京都、具体的には東京しごと財団の事業ですけれども、雇用環境整備事業の一環として、中小企業、建設業やＩＴ、ものづくりといった企業に対して、大学生等が奨学金の返還費用を返す際の一部を助成する事業を実施しています。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"利用されているということで、とてもすばらしいと思います。一方で、あまり利用が多くないということですが、課題は何と考えますでしょうか。","respondent":"小林地域産業振興課長","answer":"先ほどご説明したとおり、本事業は東京都の助成事業ですので、品川区はそこに上乗せをしていますけれども、やはり東京都全体で使える事業であるということ。","id":"exchange-019"},{"speaker":"山本委員","kind":"提案","question":"助成額の拡大の検討も要望し、次の質問に進みます。次に、外国人材受入・定着支援事業について伺います。ついては、以下、幾つか提案いたします。このような枠組みの創設や、枠組みの中での一部費用助成等を検討できないでしょうか。２つ目は、外国人労働者の住環境に対する助成拡大です。３つ目は款が異なりますので、連携を要望することにとどめます。それぞれ、区のご見解を伺います。","respondent":"小林地域産業振興課長","answer":"この中で、改正法は３年後の２０２７年度までにですけれども、こうした国の動きや、あるいは、やはり日本語の教育の問題、ご指摘いただいたような部分、定着といったところも課題と考えておりますので、そういったところを含めながら。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"一定やっていただいているということで、ただ、モンゴル高専だけでなく、ほかの事業にも幅広くご対応いただけるように、引き続きやっていただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"３１３ページ、環境調査測定費について、３２７ページ、景況調査委託について伺います。伺いますけれども、こちらの調査の対象には、個人事業主やフリーランスは入っているのでしょうか。伺いたいと思います。それと、毎回、特別調査というのが、定例の調査以外に実施されているのですが、特別調査の調査項目というのは、どなたが決めているのか、どのように決めているのか、伺いたいと思います。","respondent":"小林地域産業振興課長","answer":"その対象です。現在、ご質問のとおり、６業種を対象にしていますけれども、こちらにつきましては、品川区の産業構造といいますか、産業の実態を踏まえて、主要な産業、品川区を代表するような業種を中心に、定点観測という意味で景況調査を行っているものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"意見","question":"今定例会で、「事業者へのインボイス制度の影響について品川区内実態調査実施の陳情」がかかっておりまして、総務委員会では採択しておりますけれども、担当の課長が答弁の中で、実態調査について聞かれて、これは実施の有無だと思うのですけれども、この調査についても、責任ある政策判断および施策実行の権限、専門的知見を有する国において判断すべきとおっしゃっております。","respondent":"小林地域産業振興課長","answer":"ただし、私が総務委員会でご答弁した内容としまして、実態調査、いわゆる個人事業主や、あるいは課税情報を含めた、制度の影響がどうかというところを我々として把握するのは困難であると考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"それにしても、アンケートで影響を聞いているわけですから、私は可能だと思いますし、やっていたことをご存じでしたかというのは、今の答弁だと、ご存じだったという話だと思うのですけれども、伺いたいのは、景況調査でやっていたということを、何で総務委員会のときに一言も、審査のときに説明しなかったのか、解せないのです。理由を伺います。","respondent":"小林地域産業振興課長","answer":"我々としましては、その制度を具体的に、例えばですけれども経営に与える実際の影響や、あるいは税の減免手続の例えば複雑さといったご意見がありますけれども、そういったものまで含めて詳細に分析し、また確実に把握するというのは困難であると、引き続き考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"やっているのですから。ただし、フリーランスや個人事業主が入っていないということもありますので、私が改めて伺いたい、求めたいのは、まず特別調査に、しかも開始から１年たっています。直後の調査だけしか、まだやっていないので、改めて中小企業におけるインボイスの売上げや税負担、契約や取引への影響などを聞く調査項目で調査していただきたいと思いますけれども、いかがでしょうか。","respondent":"小林地域産業振興課長","answer":"インボイス制度の影響ですけれども、具体的に経営相談などで出てくる声、あるいは実際、ご相談いただく中での要望というものも、今後、我々としては引き続き把握はしていきたいと思いますけれども、いわゆる実態調査という部分で。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の答弁だとその姿勢が感じられないので、これは本会議でこの陳情を採択して、議会から求めないといけないと私はますます思いました。全ての自由記述意見が基本的にホームページで公開されていますけれども、ただいま紹介した声の率直な感想はいかがでしょうか。伺いたいと思います。これは、大気汚染、電波障害について、環境調査測定が必要な案件ではないかと思いますけれども、いかがでしょうか。","respondent":"中西環境課長","answer":"自動車排ガスに関しましては４拠点で調査を行っているところでございまして、令和元年度からの数字でいきますと、浮遊粒子状の物質測定やＰＭ２.５の測定、それぞれが環境基準内に収まっているといった状況になっているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"自由意見を「大気汚染」、「電波障害」というキーワードで検索すると、大気汚染が１４５件、電波障害が１３６件もあるのです。これは区が実施したアンケートなのですから、出た声に対して調査するというのは行政の責任だと私は思いますので、実施を強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"私からは、２９５ページ、健康づくり支援事業費、３１３ページ、太陽光発電・蓄電池システム設置助成、３２０ページ、産業経済費に関連して、ナイトタイムエコノミーについてお伺いいたします。令和４年度と令和５年度を比較すると倍増、登録参加者数の目標達成数が２倍になっているのですけれども、これはかなり強気な目標設定かと思うのですけれども、その根拠と理由を教えてください。","respondent":"若生健康課長","answer":"そういった状況も鑑みまして、今後、増えていくだろうということで、１年に１,０００人ずつ増えていくということを想定いたしまして、５年間で５,０００人プラスということで、令和１１年度、１万人という目標を立てているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。シナモロールをイメージキャラクターとして採用されておりますけれども、シナモロールを使用することは結構大変なことだということを伺っておりますけれども、シナモロールを採用するということは、結構、力が入っている事業かと思うのですけれども、その辺り、今後の健康ポイント事業についての意気込みというか、そうした今後の展開をお知らせください。","respondent":"若生健康課長","answer":"健康ポイント事業における、品川観光大使シナモロールの使用に絡めてのご質問ですが、シナモロールの使用につきましては、文化観光戦略課に申請を行いまして、文化観光戦略課からサンリオに申請して、許可が得られたら使えるというような仕組みになっていまして。","id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。一方、「品川区ウォーキングマップ私の散歩道」というものがまだあると思うのですけれども、これは、今始まっている健康ポイント事業と重なってしまうのかと思うのですけれども、この「品川区ウォーキングマップ私の散歩道」との関係、今後、廃止されるのか、それとも連動していくのか、今後の動向をお聞かせください。","respondent":"若生健康課長","answer":"現在、「健康プラン２１」という健康増進計画の改定作業を行っておりまして、その中でもウォーキングの重要性を議論していますので、今後、こちらのリニューアルというところも現在検討しています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ぜひ、そういった方向でしたらよろしくお願いします。そうすれば、新しく、では健康づくり推進委員活動をやってみようかという人も増えて、ひいては人材確保につながっていくかと思うのですけれども、今後、ホームページでしっかりと、現在の健康づくり推進委員の活動を載せていっていただきたいのですけれども、その点、いかがお考えでしょうか。","respondent":"若生健康課長","answer":"年に１回、健康づくり推進委員の皆さんが集まって活動報告会というのを開いておりまして、そちらに各地域の町会長をお招きしたりということで、できるだけ地域に浸透して認知度を上げていくよう努力しているところでございまして、ホームページについても。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。続いて、太陽光発電・蓄電池システム設置助成についてお伺いいたしますけれども、本当に今年も異常な猛暑で、気候変動対策をしなくてはいけないと考えております。ほかの再生可能エネルギーもあるのですけれども、なぜ太陽光発電をこうして積極的に推されているのか。やはり、現実的に太陽光発電しかないのかと私も思うのですけれども、区の認識をお聞かせください。","respondent":"中西環境課長","answer":"ただ、品川区という土地柄、再生可能エネルギー導入を進めていくに当たりましては、なかなか、太陽光以外のものですと導入の負担が大きいという部分、それから地形的にも難しい部分がありますので、国のエネルギー基本計画におきましても、太陽光が一番。","id":"exchange-032"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。今、設置助成を区でも進めておられるかと思うのですが、一方、東京都でも、そうした助成事業を結構進められていると思うので、東京都との事業の重なりがあるかと思うのですけれども、区と都で重なっている助成事業はどの程度あるのか、そして区と都が重なっている場合の対応をお知らせください。","respondent":"中西環境課長","answer":"都の補助金との併用といったところです。太陽光に関しましては、都の補助金との併用を可能としています。それから、ほかの例えば今年度開始いたしました省エネ家電の設置助成等々も、東京都のゼロエミポイントの補助事業と併用が可能といった形で整理しているものです。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"そして一方で、太陽光を推し進めるのはいいのですけれども、太陽光パネルの使用期限が大体、２０年から３０年と言われているのですけれども、そうすると二、三十年後に大量廃棄問題が出てくると思います。この廃棄の問題もやはりある程度、二、三十年というスパンですから考えていかなくてはいけないと思うのですけれども、品川区としては太陽光パネルの廃棄の問題をどのようにお考えなのかお知らせください。","respondent":"中西環境課長","answer":"リサイクルに関してですが、新聞レベルではありますが、今、国でリサイクルの義務化に向けた検討が進んでいるといったところもありますので、そういった動向を注視しながら、私どもとしても対応を考えてまいりたいと考えています。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして最後に、ナイトタイムエコノミーについてお伺いいたしますけれども、やはり観光の視点ということで、先日、私の質問でも前向きなご答弁を頂きましたけれども、やはり商業について関連して、ナイトタイムエコノミーをぜひ広げていっていただきたいと思うのですけれども、コロナの影響を受けて、先ほど、えのした委員からも飲食店についてのご質問がありましたけれども、やはり経済活動は昼と夜があって。","respondent":"小林地域産業振興課長","answer":"両課でも連携しながら、観光客にもＰＲというような取組を何かできないかということを、引き続き考えてまいりたいと思います。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"きっかけは観光でもいいのですけれども、やはり観光というのはどうしても単発になりがちなので、これを中長期的に、持続的に、夜の経済活動というのを復活させて、昼と夜、そしてひいては日本全体の経済を上げていかなければいけないと思いますので、ぜひよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日は、３００ページの母子保健費、３０５ページの予防接種費、３３１ページ、消費者啓発費から質問をします。母子保健費からは、子どもの誤飲防止について質問します。家庭内の事故は自治体が関わりにくい部分ではあるのですけれども、予防には効果的な啓発をしていく必要があり、また誤飲についても家庭内で起きやすいので、子どもがいる家庭への周知・啓発が求められると考えています。","respondent":"石橋品川保健センター所長","answer":"委員ご質問の誤飲防止の対策について、私からご回答いたします。４か月健康診査の集団指導やマタニティクラスなどの事業において、誤飲チェッカーというものを使用した指導や周知、または誤飲防止を含んだ事故防止のリーフレットを配付して、周知を実施しております。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"取組について教えていただきましてありがとうあります。そこで、今日は取組の一つである、大村市でやっております、母子手帳交付時に一緒に配付している誤飲防止啓発の缶バッジを紹介させていただきたいと思います。当区でも、母子手帳の交付時や４か月健康診査でこういったものを配付することで啓発ができないかと思ったのですけれども、いかがでしょうか。","respondent":"若生健康課長、石橋品川保健センター所長","answer":"そういったところから、妊婦の方にお渡しする際に、どのぐらいのサイズ感で入れればいいかといったところは検討が必要かと考えております。ただ、その実物が、今、保健センターに幾つかしかないので、実物をご本人に配るということはしておりませんので、今後、そういったことも含めて検討してまいりたいと考えています。","id":"exchange-038"},{"speaker":"せらく委員","kind":"確認","question":"誤飲チェッカーなども、多分各家庭で作ることもできて、すごくいい啓発だと考えていますので、検討をよろしくお願いしたいと思います。次に、予防接種の任意接種について伺っていきたいと思います。任意接種は自由診療でクリニックが金額を決めることができるので、問題ないという認識にはなると思うのですけれども、確認させてください。","respondent":"五十嵐保健予防課長","answer":"定期予防接種につきましては、現在、２３区乗り入れで実施しているということで、東京都・特別区・東京都医師会連絡協議会（三者協）で金額を定めているところになっておりますが、任意接種につきましては自由診療ということで。","id":"exchange-039"},{"speaker":"せらく委員","kind":"提案","question":"確認させていただきました。費用面でトラブルやご不安感が残らないような対策として、本日、２点ご提案したいと考えています。１点目は、ワクチンの種類別に平均価格を出していただくことです。区としてホームページなどで任意接種ができるクリニック医療機関を一覧で案内しているので、該当のクリニックへ確認していただくことでご対応いただけないでしょうか。この２点について伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"病院に金額を出すようにという指導も、できる権限がございませんので、区では実施できないという状況になってあります。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。権限や、契約している・していないというところで、今、難しいのかと感じました。こちらについて消費者センターにも伺ってみたいのですけれども、消費者を保護するために、価格の表示を進めているところだと思います。医療機関における価格表示についてはどんな対策・方法ができると思われるでしょうか。教えてください。","respondent":"小林地域産業振興課長","answer":"消費者センターでも、年間３,０００件近い、いろいろなご相談を頂いておりますけれども、医療分野でのというよりは、ふだんの契約トラブルに関するものが中心となっております。そういった問題についても引き続き、我々も研究を重ねてまいりたいと考えています。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、２９７ページ、地域医療連携、３０１ページ、母子保健指導事業費についてお伺いいたします。１点目に、母子保健指導事業費についてお伺いいたします。妊娠期からの相談事業や０歳児見守り・子育てサポート事業などにおいて、妊婦と保護者の方々との顔の見える関係づくりがどのように行われているのか、現状をご説明ください。","respondent":"石橋品川保健センター所長","answer":"委員ご質問の、妊婦との顔が見える関係づくりという点になります。通常時より保健センターでは、妊娠期や出産に向けての不安などの相談事のほか、妊娠初期の面談、妊娠８か月頃の面接を、保健センターやオンラインで実施しております。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"発達障害のある保護者の子育ては、社会性、共感性、柔軟性、多様性、適切な認知ができないなどの点において、つまずきやすい場合があるとのお話をお伺いしました。なぜかを考える。３、口頭だけではなく、図や文章などの視覚化を図る。特に保健師の方々の共感性はすばらしいものだと感じておりまして、今後も研修などにより、さらに共感性を高めていただきたいと考えていますが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"続きまして２点目ですが、担当者が替わった場合の一貫性を担保するための工夫になりますが、支援した場合は記録を取っておりますので、そちらの支援記録の共有や、あとは支援が必要なご家庭においては、保健センターの保健師が専門職で集まりまして定例会を実施しておりまして。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"発達障害のある保護者もそうでない方も、妊娠時から全てのお母さんたち、保護者の方々が、産前、産後、子育て期にわたって気軽に助けを求められるよう、引き続き相談事業や伴走型支援を推進していただきたいと思いますので、よろしくお願いいたします。２点目に、地域医療連携についてお伺いいたします。令和５年度の品川区精神保健福祉地域連絡会の開催状況など、現状と課題についても教えてください。","respondent":"三ツ橋荏原保健センター所長","answer":"令和５年に開催されました品川区精神保健福祉地域連絡会ですけれども、こちらの課題といたしましては、障害と医療、それぞれの課題がございまして、その中でも、地域のそれぞれの分野、それぞれの事業の実施の状況や法改正などの連絡・調整を行っておりました。","id":"exchange-044"},{"speaker":"横山委員","kind":"意見","question":"厚生労働省の、精神障害にも対応した地域包括ケアシステム構築に向けた事例集２０２３年度版に岐阜県の事例が紹介されています。岐阜県が設置する７か所の保健所が、住民の精神保健、福祉に関する相談、通報対応を担当しており、５つの保健所圏域に分かれて、保健所が中心となり、それぞれの圏域内のネットワークづくりや協議の場の運営等、「にも包括」構築の取組を実施しているところです。","respondent":"三ツ橋荏原保健センター所長","answer":"こちらは、先ほどご紹介いたしました令和５年度の連絡会等の中で、病状が不安定な精神障害者の方、措置入院の方などにつきまして、精神科病院のネットワークにつきましては地域保健会議などで、区内のＮＴＴ東日本関東病院、またクリニックの医師などをお呼びして。","id":"exchange-045"},{"speaker":"こしば委員","kind":"意見","question":"私からは、３０５ページの予防接種費に関連しまして、ＲＳウイルス母子免疫ワクチンのアブリスボについてお尋ねいたします。ＲＳウイルス感染症についてと、併せまして、本年の５月３１日に発売されましたＲＳウイルス母子免疫ワクチン、アブリスボについて、この２点についてご紹介をお願いいたします。","respondent":"五十嵐保健予防課長","answer":"新生児に関しましては重症になる方も多くて、気管支炎等をその後、患ったりするような方もいらっしゃると認識しております。新しく発売されたアブリスボというワクチンですが、こちらに関してはＲＳウイルスに関するワクチンになってあります。","id":"exchange-046"},{"speaker":"こしば委員","kind":"質問","question":"ただいま課長からご説明がありましたように、ＲＳウイルス感染症というのは、乳児の赤ちゃんにとりまして最も危険な感染症の一つですが、国立成育医療研究センターによりますと、１歳までに約５０％、そして２歳までにはほぼ１００％の子どもが感染するという報告があります。この母子免疫ワクチン、アブリスボに対する品川区の評価についてお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"ＲＳウイルスワクチンについての考え方ですが、現在、国で定期接種化するかどうかという検討が行われているところです。特に妊婦に対する投与につきましては、やはりセンシティブな話になりますので、しっかりとした検討が必要と考えております。","id":"exchange-047"},{"speaker":"こしば委員","kind":"質問・要望","question":"アブリスボは、同じＲＳウイルスワクチンであります、ほかの例えばアレックスビーとともに、高齢者の肺炎予防にも適用がありますが、母子健康に有効なのはアブリスボだけと言われております。ぜひ将来の子育て家庭の負担を軽くするために、そして生まれてくる赤ちゃんをＲＳウイルス感染症から守るために、アブリスボの接種費用の一定の助成を強く要望したいと思いますが、区のご見解をお伺いいたします。","respondent":"五十嵐保健予防課長","answer":"ですので、国の検討会を待ちまして、定期接種化されるのを、様子を見ながら検討させていただきたいと考えております。","id":"exchange-048"},{"speaker":"こしば委員","kind":"質問","question":"現状、大変厳しい課題であると、よく分かりました。そのときは大変、専門家の間では高く評価されたと聞いております。ぜひアブリスボも、定期接種化されることはないと思われますので、費用の助成の検討を併せてお願いするとともに、このワクチンそのものを、これから品川区のホームページ等を使って、ぜひ区民に周知をお願いしたいと思いますが、最後、その周知についてご見解をお伺いしたいと思います。","respondent":"五十嵐保健予防課長","answer":"周知についてですが、現在は周知を全く行っていない状況です。様々な予防接種につきましての周知は必要かと考えますので、状況を見ながらホームページ等での周知も考えていきたいと考えています。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３０５ページの帯状疱疹ワクチン接種助成、それから３０７ページのアピアランスケア支援経費、それから３１５ページ、もったいないプロジェクト等、もし時間があれば３１１ページのそ族昆虫防除対策費というふうに伺っていきたいと思います。初めにお伺いしたいのは連携協定の内容です。どういったものになっていくのかというところでお伺いしたいと思います。","respondent":"中西環境課長","answer":"事業者と検討していますが、品川区としましては、もったいない、食品ロスに関する広報ＰＲ活動、それから事業者としましては、もったいない推進店のご紹介といったことも含めまして、連携ができないかといったところで、今、調整しています。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"アプリ事業者との連携協定というのは１社を想定されているのか、アプリ事業者を私は１社ぐらいしか具体的なものはあまり知りませんけれども、もしかしたら複数、いろいろ有効なアプリがあるのかもしれませんけれども、そういったことで包括的な連携協定みたいなものを考えているのかというところを１つ確認させていただきたいのと、このアプリの協定が結ばれて。","respondent":"中西環境課長","answer":"大きく包括というよりは、食品ロス関係のところで連携協定ができればと考えているところです。それから、今後進めていくに当たりましては、どういったイベントがいいのかといったところもありますけれども、様々な形を検討してまいりたいと思ってあります。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。ぴったり余らないように作るというのではなくて、普通、やはり商売の中では、５％ぐらいの廃棄というのは計画上の中に織り込んで、生産というか、作っていく。これは１つ、今回のアプリを展開する上でも大事な考え方かと思いますけれども、最後に区のご見解をお伺いしたいと思います。","respondent":"中西環境課長","answer":"委員のご指摘のとおりかと存じます。今、導入を検討していますアプリに関しましても、いわゆるレスキュー隊というような言い方をしているものです。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に３０５ページの帯状疱疹ワクチン接種助成の件をお伺いしたいと思います。これは２回打つので、掛ける２ということで助成をしていただいております。助成額は、２分の１は都の補助で助成しているというところがあるのですが、いろいろな補助の、区による違いの中で、都の助成額は、常に２分の１は区のやり方に応じて補助されるものと捉えてよろしいのでしょうか。教えていただきたいと思います。","respondent":"五十嵐保健予防課長","answer":"帯状疱疹ワクチン助成についての東京都の補助についてですが、区が実施しているものの半額の補助をしていただいていると認識しています。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問","question":"ということは、やはりたくさん助成すると、その半額は都に持っていただけるという考え方にもなるかと思うのですが、特に新宿区のような、接種された方の負担額は一定にして、残りの部分を助成するというやり方は非常に、先ほどの医療機関による金額の違いによって、どうしてみたいな話が必ず任意接種には付きまといますけれども、そういったこともなくなって、よいやり方なのではないかと思いましたけれども。","respondent":"五十嵐保健予防課長","answer":"すみません。記憶が確かではないのですが、上限か何かがあったように記憶しておりまして、それで恐らく１万円とか１万１,０００円の区が多かったのはそのせいではなかったかと考えております。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。次に、３０７ページのアピアランスケア支援経費ということで、これは令和５年度から開始された事業です。一方で、都の補助額というのは上限が１０万円ということになっておりまして、そういった意味では、上限３万円と品川区が今している理由について、初めにお伺いしたいと思います。","respondent":"若生健康課長","answer":"区の検討段階のところでの各先行区等の調査におきましては、大体ウィッグや胸部補正具について、他区の状況を見ますと上限３万円でやっているところがほとんどだったというところと、購入実績も数区に調べたところ、その購入額については七。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問・要望","question":"ポイントというのが各区の人口規模によって決まって、それで使える予算の上限が決められるというような類いのものと伺っていますけれども、これが、アピアランスケアの補助額を、例えば上限３万円から１０万円、マックスで使えるようにしましょうとしたときに、何かしら、包括補助としてほかの事業に影響が出てくるというようなことが懸念されるのかどうか。そこについて最後にお伺いしたいと思います。","respondent":"若生健康課長","answer":"アピアランスケア事業については、ポイントの上限の制限から外れておりますので、そういったことは影響しないと考えております。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"本日もよろしくお願いいたします。本日は、３０５ページ、予防接種費、新型コロナウイルスワクチン追加接種についてお伺いいたします。令和６年９月１９日分までの集計ですが、現在も随時更新され、その数は増えています。これまでの全てのワクチン、４７年分の合計と比べて、今回のコロナワクチン健康被害者の数は、たった３年でこの数字となっています。お聞きします。このデータを見てどう思われますか。","respondent":"五十嵐保健予防課長","answer":"コロナウイルスの健康被害についてですが、３年にわたって予防接種を実施してまいりましたので、品川区でも相談される方がいらっしゃいますので、調子の悪い方、予防接種を受けた後に具合が悪くなった方などが申請されている状況と考えておりますので。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"確認","question":"次の資料です。全国有志医師の会が２０２４年８月に出している報告のデータを共有します。政府やマスコミは言いませんが、日本の新型コロナワクチン政策は果たして正しかったのでしょうか。さて、一般の予防接種に関しましては、平成１１年、地方分権一括法で自治事務と再確認されていますが、今回のコロナワクチンに関しては法定受託事務でした。今年４月からは定期接種です。見解をお聞かせください。","respondent":"五十嵐保健予防課長","answer":"定期予防接種として実施されるものですので、もちろん私どもは実施していくという形になりますが、予防接種に関する情報につきましては、ホームページ等で周知はしてまいりたいと思ってあります。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３１３ページの温暖化対策事業に関わって、気候危機打開に向けた取組について伺います。品川区はゼロカーボンシティしながわ宣言を行い、２０５０年までにＣＯ２の排出をゼロにする目標を掲げています。しかし、２０５０年間近で急激に削減すればいいというものではありません。その認識を品川区も持っているかどうか伺います。","respondent":"中西環境課長","answer":"ゼロカーボンに向けた取組ロードマップといったところです。品川区環境基本計画の中でも、２０３０年度カーボンハーフ達成実現に向けてということでうたってあります。２０３０年度までにカーボンハーフを達成するといった意気込みは持っているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"これをさらに進めていっていただきたいと思いますけれども、この間も指摘していますが、具体的にどうやって実現していくのかということが重要です。は２０３０年カーボンハーフに向けて、年度ごとに省エネ、また再生可能エネルギーでどれだけ削減するのかということなど、具体的なロードマップを示すべきだと思いますが、いかがでしょうか。","respondent":"中西環境課長","answer":"そういったものもにらみながら、様々取組を進めてまいりたいと考えているところです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、再エネ、省エネでどれだけ減らしていくのかと。どちらも５０％なのか、それとも省エネのほうが多いのか、再エネのほうが多いのか。そういうことを含めてやっていかなければならないと思いますけれども、いかがでしょうか。","respondent":"中西環境課長","answer":"ただ、その中でもエネルギーの使用量や運輸部門での取組といったところによって、一部、出っ張り引っ込みはあるのかと考えていますが、総体としては５０％削減といったところを目標にしているものです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのために、しっかりと取り組んでいただきたいと思います。加えて、先日の総務費の審査でもありましたが、区有施設の太陽光発電設置検討では、新規設置が３２３ｋｗ、１７０ｔＣＯ２の削減。太陽光発電だけでやるわけではないですけれども、やはりこれを増やしていかなければ達成できないと思いますので、どうやって再エネを増やしていくのかというところを伺いたいと思います。","respondent":"中西環境課長","answer":"１つは太陽光を増やしていくといったところで、今取り組んでいるものです。それから、これは今、東京都でも動いているものですが、例えば水素由来の電力を使うなど、様々、今、技術革新等も起こってあります。そういったものも含めながら検討してまいりたいと考えています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"提案","question":"その場で発電して使うというのが一番だと思います。そのためにも、住宅を建築する際の地球温暖化対策の相談窓口を設置することを提案しますが、いかがでしょうか。併せて、早期に設置を進めていくために、初期投資ゼロで太陽光発電を設置できる屋根貸しの事業を、ほかのところでもいろいろやっていると思うのですけれども、区としても推進すべきだと思いますが、いかがでしょうか。","respondent":"中西環境課長","answer":"太陽光発電の設置助成に絡めまして、促進するためのご提案を頂戴したところです。実際、我々としてもどのように拡大していくかといったところの検討を今進めているところです。様々、どういった形がいいのか検討してまいりたいと思います。","id":"exchange-063"},{"speaker":"のだて委員","kind":"提案","question":"具体的に相談窓口の設置や、初期投資ゼロで設置できる屋根貸し事業ということで提案させていただきました。やはり、初期投資ゼロで設置できるというのは、気候危機対策に本当に抜本的に取り組んでいかなければならないというところで、それだけのことをやっていかないと進んでいかないということだと思いますので、ぜひ考えて、進めていっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中西環境課長","answer":"私どもで課題と考えているのは、いかに事業者向けにも周知していくかといった部分も検討の課題かと思ってありますので、家庭部門、業務部門を含めまして、どういった形で周知して、設置に向けて進められるかといったところについて、検討してまいりたいと考えています。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問・要望","question":"超高層ビルはそもそもやめるべきだとは思いますけれども、ほかにもマンションは増えていますので、区内の住居は共同住宅が８割という状況ですので、対策が必要だと思います。区として賃貸住宅への太陽光発電設置に向けた取組を進めているのか伺いたいのと、今、助成事業で賃貸住宅は何件あるのか、割合も伺えたらと思います。","respondent":"中西環境課長","answer":"太陽光発電に関しましては集合住宅も対象とさせていただいているものです。細かい内訳に関しては、今、持ち合わせてございません。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ賃貸住宅も含めて設置できるようにしていただきたいと思いますし、再エネだけでなく省エネ分野でも大きく進めていかないと、カーボンハーフ、カーボンゼロを実現できないと思いますので、抜本的に取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"確認","question":"私からは、３０３ページ、産後ケア事業について、３０５ページ、がん検診普及事業について順不同で、また、さらに時間が許せば２９７ページ、休日・小児夜間診療費について質疑します。本区ではがん情報をホームページで、令和４年１月から運用を開始していると確認しています。関心の高まりを感じておりますが、この閲覧数が伸びた件について区はどのように分析しているのか、お答えください。","respondent":"若生健康課長","answer":"品川区のがん情報ホームページの閲覧数につきましては、委員のご指摘のとおり、かなり伸びているところでございまして、要因としましては、やはり、がん検診も地道に広報やＳＮＳなどで周知・啓発をしているところと、令和５年度はアピアランスケアの事業も開始しておりますので。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"意見","question":"先ほど塚本委員の質疑でもありました、令和５年７月からのアピアランスケア事業によって、ウィッグや胸部補整具の購入助成が開始されており、このような新規事業の開始なども、確かにホームページの閲覧数の向上に関係しているのではないかと私も推測いたしました。予算では１６０件程度の助成を想定し、４８０万円の予算を計上しておりましたが、令和５年度の実績についてお答えください。","respondent":"若生健康課長","answer":"アピアランスケア事業の実績です。予算上、１６０件というところに対しまして、助成については１４９件の助成をしておりまして、実績額につきましては、助成総額が４２３万６,１２８円となっています。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"質問・要望","question":"令和５年７月から開始ということでありますが、４月から遡って支給するということも、議事録を通して確認しています。１点、ＡＹＡ世代、１５歳から３９歳、思春期または若年成人の世代を指すのですけれども、ＡＹＡ世代のがんの支援というところも重要になってくるのではないかと考えていますので、その点についても焦点を当てて質問をさせていただきたいと思います。","respondent":"若生健康課長","answer":"若年世代、いわゆるＡＹＡ世代のがんについての認識です。区といたしましても、若い世代や働き盛り世代というところでのがんについて、非常に対策を進めていかなければいけないと認識しています。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問・要望","question":"「ＡＹＡ世代のがん患者の在宅医療・療養、緩和ケアに対して、今後充実させる必要があると考える取組は何ですか」という質問に対して、結果としては、ＡＹＡ世代のがん患者に対応できる在宅医療・療養を支える医療人材の育成が６７.４％と最も高く、次いで、患者の費用負担の軽減というものが６３％というような結果になっております。１件、福岡市の事例を説明します。","respondent":"若生健康課長","answer":"若年がん患者への在宅支援事業についてですが、幾つかの区や、ほかの自治体で先行して、４０代未満で介護が必要な方への経済的支援を行っているというところは認識しています。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私は担当の看護師だったので、家族にもご相談をして、どうしたいですかと意向を聞いたところ、家族は自宅で見たいということで、ご自宅に帰るという決断をしました。このような方々が希望したときに、自宅でしっかりと見ていける、そして費用の負担がないというところは、国の動向だけではなくて品川区としても考えていかなければいけないかと思いますので、こちらについては重ねて要望します。","respondent":"石橋品川保健センター所長","answer":"は日帰り型が減少した理由になりますが、令和４年度はホテルにて実施、令和５年度は保健センターにて実施させていただきまして、実施場所の変更や、ケアメニューの内容に変更があったことが減少した要因と考えております。","id":"exchange-071"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ケアメニューの変更などによって減少してしまった。逆に、そこの内容が変わったこと、対象者が拡大したことによって、増加したということが把握できました。予約方法について、前回の決算特別委員会でも指摘させていただいたのですけれども、ぜひ予約をデジタル化してほしいというような要望をさせていただいておりました。現在の状況、また今後の方向性についてもお知らせください。","respondent":"石橋品川保健センター所長","answer":"日帰り型と訪問型につきましては、まだ電話での申込みという形を取っているのですが、宿泊型の利便性が高いことが評価されておりますので、今後、日帰り型、訪問型についても、電子化について検討を進めていきたいと考えております。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問","question":"最近、出産した方から、どうですかということを聞いたときに、やはり、なかなか紙や電話などというところはハードルが高いというようなお話を受けて、品川区がこうやって宿泊型についてまずは電子化ができたということは、大変うれしく評価しております。実際に、この回数の増加、そして対象者の拡大に対する区民の声などがありましたら、お聞かせいただければと思います。","respondent":"石橋品川保健センター所長","answer":"５回利用できる、複数回利用できることに対しまして、成長のタイミングに合わせて利用できるということが、回数の増加や、使用できる月齢を延長したことの成果が着実に出ているものだと認識しております。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"１回ではなかなか分かりにくいというところが、何回か利用することによって、そしてリピーターが増えることによって、お困り事、月齢に応じた対応というところができると思います。ぜひこの事業について引き続き拡大していきながら、課題についても解決していただければと思います。もう一点聞きたかった休日・夜間診療の件については、また別の機会を設けまして質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"３１１ページの衛生許可および監視指導より、災害時におけるキッチンカーの営業許可について伺いたいと思います。ただ、都全体として明確な考え方が整理されたものは確認できないと説明がありました。都全体ではまだ整理されていないということですが、品川区としても、しっかり整理していただきたいと思いますが、それぞれいかがでしょうか。","respondent":"赤木生活衛生課長","answer":"予算特別委員会でも答弁させていただいたとおりという形になりますけれども、無償で災害支援を行う場合というのは、一般ボランティアによる炊き出し行為と同様に営業行為には該当しないため、新たな食品営業許可は不要であるという考えです。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"該当しないということで、新たな許可は必要ないということでした。品川区が被災地となる際、キッチンカーで無償の食糧支援を行う際には、そういう対応だということで確認させていただきたいと思いますが、そのことを、品川区のホームページに、ぜひ掲載していただきたいと思いますが、いかがでしょうか。","respondent":"赤木生活衛生課長","answer":"ホームページへの掲載につきましては、キッチンカーがどこに配置されるのかという部分としまして、避難所運営等に係る事項という形になるかと思いますので、こちらは基本的には防災計画の中で、ホームページ等も含めて整備されていくものであると認識しております。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に、災害時に不慣れな方が大量に食事を調理することはとても大変です。ぜひ、いつ起きてもおかしくないと言われている災害のことでありますので、早急に整えていただきたいと思いますが、いかがでしょうか。ぜひといいますか、踏み出している自治体も伺っておりますので、いつまでにといいますか、スケジュール感を持って進めていただきたいと思いますが、いかがでしょうか。","respondent":"赤木生活衛生課長","answer":"ホームページでの衛生状況や、キッチンカーの営業許可に関する案内というところですけれども、繰り返しとなりますが、防災課と連携しまして計画を持って進めてまいりたいと考えています。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ防災課と連携して進めていただきたいと思います。その点において、先ほども指摘いたしましたが、災害時における保健所の役割は極めて重要だと思います。避難所の運営や受入れ体制などということは、防災課と連携するところも多いかと思いますけれども、災害時において、食事の管理・提供、メニューや献立も含めて、保健所の力の発揮を重ねて要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"西村委員","kind":"確認","question":"２９９ページ、公害健康被害予防事業費、３０１ページ、乳児健康診査、３０５ページ、予防接種費を、順不同で伺ってまいります。乳児健康診査から、小児健康相談について伺います。事務事業評価シートを確認し、執行率も高く、有効な事業だと考えています。どういう場面で使われているのか、この事業の詳細をお知らせください。","respondent":"石橋品川保健センター所長","answer":"乳幼児健康診査は、１歳６か月児健康診査、３歳児健康診査の結果、発育や発達等に遅れがある場合、また養育者の不安が大きいご家庭は、経過観察や発達健診などを実施し、その後、発達相談室などの関係機関につなげ。","id":"exchange-079"},{"speaker":"西村委員","kind":"意見","question":"例えば本事業の心理経過観察、個別は、令和５年度の目標数６００件に対して、実績が７８９件と記載があります。その他取組も高い水準を推移しておりますので、マンパワーが足りているのか、ぜひ検証していただいて、足りなければ拡充をお願いしたいと考えています。そこで今、健康診査で国が進めているのが５歳児健康診査になります。国が５歳児健康診査を進めようとしている目的を改めてお聞かせください。","respondent":"石橋品川保健センター所長","answer":"特に５歳児健康診査の目的としては、個人の成長や発達を診察するだけでなく、集団における立ち振る舞い、社会的な発達状況の確認ということを、５歳児健康診査の目的として国は掲げております。","id":"exchange-080"},{"speaker":"西村委員","kind":"質問","question":"集団生活の中でというのは大きなポイントであると考えています。先般の一般質問で我が会派のせお議員から質問がありました。５歳児健康診査を実施するのであれば、単体で捉えず大きな事業の中の一つとして捉えてほしいと質問したところ、ご答弁では、健康診査後の相談支援体制の強化が課題と。そこで、区としては５歳児健康診査をどのように位置づけているのか伺います。","respondent":"石橋品川保健センター所長","answer":"５歳児健康診査を実施するに向け、子育て、教育分野などと協働し、しっかりとその後のフォロー体制も構築していくように進めるよう、検討してまいりたいと考えております。","id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"まさに、通達によりますと、保健、医療、福祉、教育の各分野における地域のフォローアップ体制の整備および分野間の連携体制について求めておられます。担当者いわく、ここまで分野を超えて支援体制を求めることは大変珍しいとのことでございました。そこで、まずは区の現状について、ＣＯＰＤに関してどのような課題を認識されているかを伺います。","respondent":"若生健康課長","answer":"ＣＯＰＤに関しましては統計的に公式なものが存在しないということで、品川区内での患者数がどのぐらいというのは把握していない状況ではありますが、全国的な状況としましては、潜在的には５３０万人以上の患者がいるとも言われておりまして、初期症状としては。","id":"exchange-082"},{"speaker":"西村委員","kind":"質問","question":"私も今回いろいろと調べておりまして、特に死亡者の９割以上を７０歳以上の高齢者が占めているという点、急速に高齢化が進む中で、対策を進めていく必要があると考えています。そこで、疾患啓発の取組について、ＣＯＰＤの疾患啓発の区の取組を教えていただければと思います。","respondent":"若生健康課長","answer":"世界禁煙デー、禁煙週間や、９月の健康増進普及月間においても禁煙・受動喫煙防止の啓発を積極的に行っておりまして、また、毎年１１月第３水曜日に世界ＣＯＰＤデーというのがありますので、そういったところでの普及・啓発も検討しています。","id":"exchange-083"},{"speaker":"西村委員","kind":"質問・要望","question":"その他啓発もぜひ力を入れていただきたいと思うのですが、令和７年度より次期健康増進計画がスタートしていく中で、ＣＯＰＤの死亡率の減少や認知度の向上に関して、どのような目標を設定して重症化予防に取り組む予定なのか、伺ってまいりたいと思います。死亡率の減少など、ＣＯＰＤ対策についてどのような目標を設定していくのか伺います。","respondent":"若生健康課長","answer":"「しながわ健康プラン２１」へのＣＯＰＤの取組の反映というところになりますが、まず国で設定している死亡率等といったところですが、先ほど答弁させていただいたとおり、ＣＯＰＤの罹患率等について区で出すのが難しいというところで。","id":"exchange-084"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、ＨＰＶワクチンについて伺いたいと思います。キャッチアップ終了まであと半年あります。キャッチアップ接種の対象者で未接種の方、また定期接種の対象者でも高校１年生の未接種の方で、９月中の１回目接種が間に合わなかった方が諦めてしまわないように、短縮スケジュールで年度内に接種が完了できるのだということを周知していただきたいと思いますが、区のお考えを伺います。","respondent":"五十嵐保健予防課長","answer":"問合せがあったりした場合にはご説明させていただいて、４か月で打てる方法もありますので、接種する医師とご相談くださいということは説明させていただいているような状況になってあります。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、男子の任意接種補助について伺いますけれども、この補助事業が来年度も続くのであれば、こちらも年度をまたいでも、大半の対象者は補助を受けられますが、来年度に対象から外れる高校１年生は、途中から補助を受けられない可能性が高くなってまいります。現状、どのような救済措置を検討されているのか伺います。","respondent":"五十嵐保健予防課長","answer":"現在のところ、４月から周知をさせていただいていた関係もありまして、高校１年生が今年度で終わってしまうということは承知しているところですが、現状では特に延長する考えは持っておりません。","id":"exchange-086"},{"speaker":"西村委員","kind":"意見","question":"対象学年の高校１年生相当の方は、３回目接種が間に合わない場合がある、またそれがどれぐらいの方々に影響を与えるのかということも改めてお調べいただいた上で、ご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私は、３０７ページ、自殺予防対策事業と、３２７ページの中小企業活性化事業費に関連してお願いいたします。品川区自殺対策計画の直近３年の目標値を教えていただいてもよろしいですか。自殺死亡率の目標値を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"確認","question":"少しずつ減らしているという感じになっていると思うのですけれども、それを踏まえて、今年の予算特別委員会での私の質問への答弁の件の確認ですけれども、自殺率の目標値というのは、大体どこの自治体も自殺対策計画みたいなものに盛り込まれているのですけれども、これは必ず明記しなくてはいけないものではないと認識して、そういった答弁を頂いていると思うのですが、その確認を一応したいのですが。","respondent":"五十嵐保健予防課長","answer":"数値目標についてですが、必ずしも書かなくていいということにはなってありますが、ただ、自殺対策の目標を共有するということで、共通の認識をするために目標値は定めることとなっておりまして、目標率でなくても、人数などでもいいので。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"提案","question":"それで、私からの要望というか提案なのですけれども、やはり人口当たりの自殺率は基本的にはゼロを目指すべきだと考えておりまして、そういった中で結果的に自殺者が出てしまうのは致し方ないとしても、やはりゼロを目指してほしい。これはなぜかというと、親族が自殺をされた遺族の方とお話ししたときに私は、品川区の自殺率というのは他の自治体に比べて低いのです。なるほどと。あれば教えてください。","respondent":"五十嵐保健予防課長","answer":"具体的な根拠と言われますと難しいところではありますが、国で令和８年までに自殺死亡率を平成２７年と比べて３０％減少させると目標を定めているところから、０.５％ずつ、少しずつ下げられるようにということで示させていただいているものです。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"意見","question":"つまり、逆算して書いているだけで、明確な根拠というのは多分ないと思うのです。特に自殺率に関して言うと、分母が４０万人ぐらいいて、分子が数十人とか数人なわけです。というと、毎年、かなり誤差が出やすい。つまり、毎年、かなり誤差が生まれるわけで、目標を立てるというのも難しいわけです。何か受け止めがあればお願いします。","respondent":"五十嵐保健予防課長","answer":"ただ、当面の数値目標として、先ほど申し上げました３０％以上減少というようなものも挙げておりますので、区でもそのような形で書かせていただいているところですが、今年、自殺対策計画の見直しを行っておりますので、協議会等もやっておりますので。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ考えていただければと思いますので、お願いします。次です。中小企業に関してですけれども、飲食店の倒産件数が過去最多ペースだということで、非常に中小企業、飲食店は苦労していると思うのですが、品川区も例外ではないと思うのですが、区としてはどのように今のこの状況を受け止めておりますでしょうか。","respondent":"小林地域産業振興課長","answer":"現在の令和６年度の倒産の推移というのを見ますと、これはコロナ前、令和元年ぐらいの状況に近いペースなのかと。ただし、全国的に見ますと、この１０年間の中でも、これはやはり悪いペースといいますか、かなり中小企業にとっては厳しい経済状況になっていると認識しています。","id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それはどういうお店かというと、いわゆる二郎系という、区長や田中たけし委員の三田会の方がこよなく愛している二郎系ラーメンのお店で、安い料金でたくさん食べられるお店なのですが、これを何で今言ったかというと、今、ラーメンの価格がすごく上がっていて、普通に食べて９００円、トッピングをつけると１,０００円を超えてしまうと。１年少し前まで７００円だった。何か最後にあればお願いします。","respondent":"小林地域産業振興課長","answer":"ラーメン店、飲食店につきましては、今回の９月補正の予算も十分活用いただけるのではないかと考えています。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３０７ページ、精神保健事業、時間があれば３０５ページの帯状疱疹ワクチンについてお聞きします。精神保健事業からお伺いしたいと思います。精神疾患、精神障害の疑いのある方の相談と対応についてお聞きしたいと思います。近所の方が大変困っている。いやいや、このご家族はどうすればいいのですか。そこの対応、対策を考えていただきたい。こうした事案についてどうお考えでしょうか。","respondent":"三ツ橋荏原保健センター所長","answer":"今回の場合につきましては、警察と連携を取りながら、また保健師や心理士などにも相談しながら、その方に対する対応を、どのように医療につなげていくか、また重い医療なのか、それとももう少し軽い医療なのか。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"警察の方がその後、動いてくださったようで、そのお宅の、疾患の疑いのある家族に接触していただいてという形でつながったのですが、警察も、先ほど申し上げたように、第２３条でないと動かないというようなところもあるので、そこはどうかもう一歩、保健センターからも、こうした対応についての連携というところを取っていただきたい、体制をつくっていただきたいと思うわけですが、いかがでしょうか。","respondent":"三ツ橋荏原保健センター所長","answer":"近隣の方からの様々なご用件、ご要望がある中で、またご当人の人権侵害などを考えながら対応していかなければならないと考えています。ただし、警察との連携に関しましては、しっかりと連携を取っていきたいと思いますので、よろしくお願いいたします。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。民事不介入というところで、なかなか保健センターは動けないといったところであるかもしれないですが、警察と連携を取って、状況を把握して、適切な医療につなぐ、家族との接触などを図っていただける対策をつくっていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、３０５ページ、予防接種費の子宮頸がんワクチンキャッチアップについて、３１３ページ、環境調査測定費に関連して羽田新飛行ルートについて、時間があれば３２１ページ、中小企業センター運営費について、それぞれお伺いします。改めてその辺をお伺いします。１１月までまだ可能ですので、ぜひそこは品川区の本気度も見せていただきたいと思いますので、改めてご答弁いただければと思います。","respondent":"五十嵐保健予防課長","answer":"ただ、やはり、ずっといつまでもやり続けるのがいいのかという部分もありますので、あまり長い期間、もう今、キャッチアップをやっている方で一番年齢が高い方は２８歳の方になりますので、やはり子宮頸がんワクチンの目的からすれば。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"意見","question":"さらに言えば、２回は公費で打てるのだからというお話がありました。実は宮崎市で先月、３回目の接種が年度をまたいでも、市でしっかりと助成をするということで発表しました。これです。やるべきだと思います。こういったことも含めて、もう一度、３回目の接種が年度をまたいでも助成をするべきだと思いますが、区のご見解をお聞かせください。","respondent":"五十嵐保健予防課長","answer":"子宮頸がんワクチンのキャッチアップにつきましては、３年前ぐらいからやらせていただいていたかと思います。その件もありますので、今のところは特に、キャッチアップのフォローをさせていただいて延ばすということは考えていないところです。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"コロナ禍で、なかなかこのワクチンを打つこともできなかったのが現状ではないでしょうか。これは要望で止めておきますが、ぜひお願いしたいと思います。次に行きます。実は自分も分からなかったので、まだこれからどんどん、これは深掘りしていきたいと思いますが、区として、こういった飛行機の影響が実際、区民にあることを、認知されているのかどうかお聞かせください。","respondent":"高梨都市計画課長","answer":"羽田新飛行ルートに係る様々な声、区へのお問合せは都市計画課で受けておりますので、私から答弁をします。今、委員からお話のありました、お子さんに蕁麻疹のような症状が現れるというような内容での区への区民からのお問合せということは、今まではございませんでした。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私も分からないです。専門家ではないし、これはあくまで一例だし、私も医者のご助言の中で、まだ最終的に、本当にそうなのかどうかも確認していないですけれども、医者がそういう判断をしたということなので、ぜひ、こういったいろいろな影響があるのです。「要望書を届けました。この要望書が、どうやって国土交通省に行って、国土交通省の中で議論があって、その答えはいつ返ってくるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"石田（し）委員","kind":"意見","question":"それも含めてどういった調査をしているのかをお知らせください。","respondent":"高梨都市計画課長","answer":"この間の要望書を提出した後の動きですが、要望するとともに、しっかりと区民負担軽減につながる取組を早期に検討し、実施していただくといったところも、併せて国に求めておりますので、様々な区民の方が抱える不安を取り除く動きというものを。","id":"exchange-101"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３０１ページ、小児健康相談、３１３ページ、アスベスト対策事業、同じページで高効率給湯器設置助成についてお尋ねします。最初に、３０１ページ、小児健康相談についてお尋ねします。この小児健康相談というのは幅広い相談があるかと思いますけれども、主にどういった相談が多いのかというのをお知らせいただきたいと思います。","respondent":"石橋品川保健センター所長","answer":"小児健康相談の主な内容についてのご質問になります。こちらは、お子様の発育や発達に対して、通常と比べて少し遅れているのではないかというような相談を、主に頂いているところになります。","id":"exchange-102"},{"speaker":"高橋（伸）委員","kind":"提案","question":"特に実習と練習が私は必要だと考えています。安心して、子どもの子育てをするための取組の提案だと、会派としても以前、強く要望してきたものであります。品川保健センター所長にお伺いしたいのは、薬を飲ませたこともない、子どもの看病もほとんどしたことがない保護者に対して、健康診査や窓口でリーフレットを配れば解決できるものと思われているのでしょうか。そのお考えをお聞きしたいと思います。","respondent":"石橋品川保健センター所長","answer":"ただ、今後、やはりそのような要望が多いというところを把握しながら、薬剤師会の方ともいろいろ知識の共有を図って、薬の飲ませ方を含めて、病気のケアについて、何か保健センター、区としてもできないかということは検討してまいりたいと考えております。","id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはりこれは十分、知識の提供とケアの仕方を習得していただく練習の場が必要ではないでしょうかと私は思っているのですけれども、いま一度、ご見解をお願いしたいと思います。","respondent":"石橋品川保健センター所長","answer":"ただ、今後、薬剤師会の方ともいろいろお話を、協議を進めさせていただいて、何かしら今よりもいい方法がないかということは検討してまいりたいと考えています。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。続きまして、３１３ページ、アスベスト対策事業、高効率給湯器設置助成についてお伺いいたします。アスベスト対策事業に対しては、やはりいろいろ建設関係の団体の方からもご要望を頂いております。これは要望ですけれども、建設３団体に対しても、ぜひ啓発・広報活動をしていただきたい。もしかしたら広報しているのかもしれませんけれども、その辺のところを２点、お尋ねします。","respondent":"中西環境課長","answer":"私どもも、今どのように周知をしていけば、より活用いただけるかといったところは検討していますので、委員にご提案いただきました建設３団体への助成と周知といったことも、改めて強化して進めてまいりたいと考えています。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それと、あともう一点ですけれども、現地に行ってアスベストの調査を行っていますよね。それは、区の職員の方が行っておられるかと思うのです。区の職員の方に行っていただくのはいいのだけれども、逆に業者などに依頼する、委託するという手法もあるかと思うのですけれども、その辺についてお伺いします。","respondent":"中西環境課長","answer":"事前調査結果報告が令和４年度から求められる形になりまして、立入り調査が昨年度ですと９６９件、職員のほうで行って、調査をしているような状況です。今後もどういったやり方がいいかを含めまして、様々、確認しながら検討してまいりたいと思います。","id":"exchange-106"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３０４ページ、３０５ページの各種健診の拡充とがん検診の無料化を求めて質問したいと思います。小児インフルエンザワクチンですけれども、お母さんから、品川区も無料にしていただけたら助かるというご要望を頂いたのですが、近隣区の状況を見ましたら、港区が４,５００円の助成をしていまして、渋谷区は全額助成をしているということで、ホームページにあったのです。","respondent":"五十嵐保健予防課長","answer":"品川区の今後ですが、高齢者のほうは定期予防接種ということもありまして、無料化をさせていただいた部分もあります。お子さんの予防接種につきましては、まだ現在、任意予防接種ということになってありますので、現在のところは無料化にすることは考えていない状況です。","id":"exchange-107"},{"speaker":"鈴木委員","kind":"質問・要望","question":"任意ということですけれども、ぜひ無料化に向けてご検討いただきたいということで要望します。さらに、医療費の１位、２位というのが、新生物が４０代以降は男女ともに、１位、２位になっている状況です。それから、そのために、お金の心配をせずに受けられるよう、がん検診の無料化を求めたいと思いますが、がん検診の無料化について他区の状況などを把握されていたら、その点についてもお聞かせください。","respondent":"若生健康課長","answer":"１点目です。健診を増やしたほうがいいというご意見についてです。当然、区で実施している様々な健診がありますけれども、それぞれ目的としては、やはり生活習慣病の予防や改善、健康増進というところから、がんの罹患率、当然、最終的には死亡率を減らすという目標でやっている。","id":"exchange-108"},{"speaker":"鈴木委員","kind":"提案","question":"既に多くの区が無料化しています。今年、共産党が予算の修正も提案したのですけれども、本当に驚くような額ではなく無料化というのはできるのです。胃がん検診では、バリウム、内視鏡、リスク検診、全部を無料にしても、１,１００万円程度です。これは共産党の試算ですけれども、区として無料化するとどれぐらいかかるというのを試算したものがあれば、教えていただきたいと思います。","respondent":"若生健康課長","answer":"それ以外の検診について、一部、自己負担いただいているところですが、それら全てを無償にした場合の試算というのは区でも行ったところでございまして、若干、受診率の増加を見込んだところ、４,０００万円程度の増加というような試算をしております。","id":"exchange-109"},{"speaker":"鈴木委員","kind":"質問・要望","question":"共産党の試算とそんなに変わらなかったのだと思いました。品川区のがん対策推進計画の中でも、がん検診を受けなかった理由の第４位が、費用がかかるからということで、１５.４％が答えているのです。そういう点からも、これぐらいでできるわけですから、ぜひ無料化していただいて、アピールもできるようにお願いしたいと思います。ぜひ続けていただきたいと思うのですが、いかがでしょうか。","respondent":"若生健康課長","answer":"前立腺がん検診について、Ｄ評価というところで頂いたところですが、これについては今年度、実施しておりますけれども、今後については、現在実施しているがん対策推進計画の策定委員会でも議論させていただいておりまして、今後。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、３１６ページの清掃事業関連、それから３２９ページの商店街支援、３２１ページ、時間があれば動物死体処理費についてお伺いします。その完全な移管を受けて、清掃体制が新たになったということを踏まえ、この１年間の成果、どのような成果があったのかをお聞かせいただきたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"北品川分室は今回、新たに再整備をするということで、それに伴って体制が変わってくるということで、今年度に関してはまだ実は体制自体は変わっていないということで、この１２月に分室の解体工事が始まりますので、それで職員が一部、清掃事務所に移ってきたということで。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"体制整備の成果をぜひ期待するのですけれども、１点伺いたいのは、平成１２年に都から区に移管されて、昨年そういう体制を変えるという発表があり、今、建設中なので、これから具体的な、本格的な体制再建が始まると思うのですけれども、約二十三、四年経過して、ようやく区独自の体制を築けることになったということですが、この部分においては、時間が大分経過しているのかと。","respondent":"篠田品川区清掃事務所長","answer":"昨年度から、荏原の清掃事務所がいわゆる荏原分室という形になりまして、品川区の清掃事務所が一本化されたということがございまして、そこから今回の北品川分室の再整備に合わせまして、全体を１つに統一した形の体制の中で清掃を組んでいくということで、今。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"あのときの縛りは、土地は区に移管するけれども、２０年間は清掃事業以外には使ってはならないという縛りがあって、それがようやく解けたので、今、別の用途か、有効に活用していただいているのですけれども、そういう縛りがあったがゆえに、二十数年、北品川分室も含めて、体制を変えることができなかったのか。そこの確認をさせていただきたい。","respondent":"篠田品川区清掃事務所長","answer":"今回の北品川分室の再整備ということで、１つのきっかけになっているところはあるので、やはり何かそういった直接的な影響がないと、なかなか動けなかったのかなという気がいたします。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。ぜひ、そういう新たな、都の縛りもなくなって、しっかりと区独自の成果を上げていただくような清掃体制を今後築いていただきたいと思います。次に、商店街の関係に参ります。品川区各所に商店街があって、大変にぎやかなまちなみを形成していただいておりますけれども、それぞれの規模に応じて、またそれぞれの要望に応じた商店街支援をしっかりして頂いていることは理解しております。","respondent":"小林地域産業振興課長","answer":"この点についての、これまでの区の支援といいますか、これは我々だけではなくて都市環境部門も協力してですけれども、都市計画道路事業を広く周知するような案内板の設置などを行うことによりまして、この中で期間限定の道路占用許可をできるようにということで。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。道路に取られてしまう側は、その後の移転先、仮店舗を設けて、また出来上がったら戻るという方も中にはいらっしゃると思いますし、完全に廃業という形の方もいらっしゃいます。動物に関してはまた改めてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"吉田委員","kind":"質問","question":"私からは、３１７ページ、資源物再商品化経費と、それから３２５ページ、品川区シルバー人材センター支援事業、２つ伺います。最初に品川区シルバー人材センター支援事業のほうを伺います。そういうことでした。この辺を踏まえて、監査意見のご報告については皆さんご承知だと思いますので、監査結果が出て、その後の対応というのでしょうか、その点についてどのようにされたかご報告を頂きたいと思います。","respondent":"小林地域産業振興課長","answer":"その点については、シルバー人材センターでも、会員間でそういったお客様から現金を受け取るときの処理について、意思の疎通というのですか、しっかり認識が同じになるようにということで、改めて会員にも周知しているところでございまして。","id":"exchange-116"},{"speaker":"吉田委員","kind":"確認","question":"ただ、手続というところについて、意識の問題もありますし、具体的な、こういう手順を踏むのだというところの共通認識が欠けているように、このご意見からは思えるのですけれども、その点については、今そういう指示が出されて、会員同士の話合いというのでしょうか、認識を共通にするようなところまで、きちんと対応が済んでいるのか、きちんと皆さんがそれに納得されているということなのか。","respondent":"小林地域産業振興課長","answer":"現在、その点は会員からもいろいろご意見を頂いているところではありますけれども、きちんと同じルールでしっかりできるように、そして一番大事なのは気持ちよくお仕事をしていただけるようにというところで、区としてもシルバー人材センターに対応を求めてまいりたいと思います。","id":"exchange-117"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。しっかりお願いします。その辺についてしっかり行っていただくことを要望いたしまして、この質問は終わります。その節はまたよろしくお願いいたします。次に、３１７ページの資源物再商品化経費で、製品プラスチックのリサイクルについて伺いたいと思います。その方法については２つ、示されております。その周知の成果は適正かつ効果的であったと思われるのか、現時点での評価を伺います。","respondent":"篠田品川区清掃事務所長","answer":"プラスチック製品の再商品化についてのお尋ねです。昨年度からモデル実施をしてまいりまして、八潮地区を皮切りに、区内の一部の地域で順次、プラスチック製品の回収をしてきたところで、本年の４月１日から全区展開をしたところです。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"その成果を伺いたかったのですけれども、私もその説明会には当然、参加させていただきました。もし何か、後でコメントがあったら伺います。それで、再商品化がもう既に求められるので、その方法は既に検討されてきたと思います。先ほど示しました２つの方法のどちらを選択するのか、もう決まりましたでしょうか。伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"こちらに関しましては、先ほど申し上げた昨年度の説明会のほか、４月の本格実施に当たりましては、様々な媒体を使いまして広報し、また区の情報番組、またちょうど清掃事務所は大崎にあるのですけれども、大崎の駅前に大きなビジョンがございまして。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問・要望","question":"世界のプラスチックごみの推計は年間３億５,３００万トンに上っています。プラスチックには様々な有害化学物質が含まれているというところから、それこそ何度も、また吉田が何か言っていると思われるかもしれませんけれども、やはり人工芝を推奨している品川区として、そのプラスチックの有害性というのをどの程度認識されているのか、お考えを伺いたいと思います。","respondent":"中西環境課長","answer":"そういった中でも、今、エコルとごしでは、紙製人工芝といったものが今後、汎用性が高くならないかといったところで、実証実験を進めているような状況です。","id":"exchange-120"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は今まで、人工芝だと、ノニルフェノールなどということばかり言ってきたのですけれども、実はＰＦＡＳもこの中に含まれているということで、これは本当に有害、内分泌攪乱作用や発がん性、それから発生毒性、低出生体重や不妊増加などにつながると考えています。ぜひ深刻に受け止めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"３０１ページの３歳児健康診査に関連して、５歳児健康診査と、地域医療連携についても時間があればお聞きしたいと思います。５歳児健康診査です。５歳児健康診査は保険でやられるわけですが、なぜ必要なのか、まず確認させてください。そのフォローアップの体制も併せて検討するということで、今年の予算特別委員会の会派の総括質疑や、また第３回定例会の、せお議員の質問にも答弁されております。","respondent":"石橋品川保健センター所長","answer":"今後、区としてしっかり体制を組んでやっていく必要がありますので、今後どういった形で他課と連携を取って協働してやっていくかということは検討してまいりたいと考えております。","id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"今回の５歳児健康診査を通して、発達障害や、いろいろな所見など精神的なものがありますけれども、このネットワークをぜひ力強く構築していただきたいという思いをすごく、この話を聞いたときに感じました。そこで、保健所管部門としてこのネットワークをこれから検討・構築するに当たっての、保健所管としての強い気持ちを、役割を、どのように考えておられるかというのを確認させていただきたいと思います。","respondent":"石橋品川保健センター所長","answer":"５歳児健康診査自体はきっかけとして考えておりまして、その事後フォローを、教育や子育て分野、障害の分野を含めまして、どのようにアプローチをかけていくかということがとても重要になってきますので、保健センターからというわけではありませんが。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"そうですね。保健所管部門としては健康診査をやって、それで本来の役割は当然終わるわけです。地域医療のほうもそのままの流れで、いわゆる医療との連携をこれから深めていくというところで、まず医師会、また歯科医師会、薬剤師会、それぞれといいますか、話合いが既にスタートしていると思いますけれども、その内容やご様子について、まず確認をさせていただきたいと思います。","respondent":"遠藤健康推進部次長","answer":"内容については、医師会とのパートナーシップというのが大事だというところで、連携して取り組む事業や、それから情報共有というところでスタートしたところですけれども、今回、第１回ということで、まず地域医療連携が今回できたということで。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"区民のためにいい施策を進めていただきたいと要望させていただいて、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"３０１ページの、すくすく赤ちゃん訪問事業と、３０３ページの０歳児見守り・子育てサポート事業の２つを併せてお聞きします。この２つの事業の目的はそれぞれ何でしょうか。お答えください。それから違いは何でしょうか。おむつを配る・配らないの違いではありません。根本的な違いは何でしょうかということです。対象者をお願いいたします。","respondent":"石橋品川保健センター所長","answer":"それぞれの違いに関してというところですが、そちらに関しましては、根拠法令や手法、内容等が異なりますので、それぞれ別の事業として必要性を感じて実施しているところになります。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問","question":"私は、この２つはダブっているところが非常にあると思っているのです。それで、見守り・子育てサポートも、おむつを配るということが口実なのでしょうけれども、それをしながら様子を伺うということだと思うのです。それで、児童センターの指導員が継続的に行って、どういう状況ですかと伺っているのです。やるのだったら、これは一緒にやったらいいではないですか。そういう考えはいかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"両者を統合するという考えは現在のところありませんで、すくすく赤ちゃん訪問や見守りおむつ定期便に行ったところで、それぞれの支援員が持ってきた情報を、こちらでは一括して今後の支援につなげていくというところを考えておりまして、見守りおむつ定期便に関しましては。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"決算の額を見ると、すくすく赤ちゃん訪問事業は２,０３９万円。委託料が１億円かかっているのです。おむつを配ればいいじゃないですか。そう思います。いいところがあるのだったら、それを取り込んでいって、すくすく赤ちゃん訪問事業は、専門性の高い、それから地域の中で子育てをするという意味では、地域コミュニティという意味では最高の仕組みだと思っていますが、その点はいかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"正直、育児用品の経済的支援ということで、それをきっかけに扉を開けていただけるというところもあるものだとは思っていますが、それをきっかけに行政が毎月しっかり関わりを取れることが重要だと認識しております。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"始まったばかりの事業ですから、また今年いろいろ課題があって、また来年度の予算に役立てていただきたいという思いはあります。やり方がどちらなのかという。何も委託金に１億円をかける必要はないではないですか。なので、ここを考えるときに、費用対効果を含め、今までやってきたことにしっかり自信を持って、それで拡大するべきところは拡大していただきたいとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"最初に、先ほど来いろいろ出ていますが、プラスチックというのは悪者ですか。それをまず、お伺いしたいと思います。海洋投棄は絶対駄目だけれども、プラスチック自体は悪者ですか。ごみの８割は、現実、燃やしているわけだ。３つ目。１日３ｔもないというぐらいです。私はもう遅いと思っていますけれども、それぐらいのことをやるべきだと私は思っておりまして、それについての考え方も教えてください。","respondent":"篠田品川区清掃事務所長","answer":"ただ、今後、様々、資源回収の道筋を考えていく中では、そういったことも検討の俎上にのせていく必要があるのかもしれないというところは受け止めさせていただいているところです。それから、八潮のし尿関係のお話です。","id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"減量化。それはもちろん分かっているつもりでありますけれども、もう限界だと私は思っておりますので、ぜひ公のところで、１回減量、それには有料化。これも必ず必要だと考えていますので、よろしくお願いします。それから、集団回収はメニューをぜひ増やしていただきたい。それからプラスチックは、あまり悪者、悪者と言わないように、ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご要望としては、４５分に短縮したものを、コース制ではなく６０分にしていただきたいと。スタジオの関係で、狭いところでやらないといけないプログラムもあるというようなご意見があったのですが、利用者の要望を積極的に取り入れたという評価をモニタリングではしているのですが、このようなご要望と、それに対する指定管理者の対応について、いかがお考えでしょうか。","respondent":"若生健康課長","answer":"健康センターのプログラム等のご要望についてですが、まず健康センターにつきましては、１回ごとに施設利用料を払っていただいて、その利用料だけでフリーで自由に参加できるスタジオプログラムを複数設けてございまして、それとは別に、数か月で１つのコースということで。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、課長にご説明いただいたのですけれども、やはり指定管理者がコース制を増やすということは、もちろん収益を上げるための取組ということで、それはそれで、その方向はいいのですけれども、以前のような形で使っていた区民の方の声をしっかりと指定管理者に伝えて、区民の方々のご意見も改善に努めていってほしいと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"ただどうしても、個別の先生を増やしてほしいなど、いろいろ個別の案件も多いものですから、なかなか１００％、全て答えるのは難しいですが、なるべくご要望に応えられるように努力しています。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ要望に応えていただきたいと思います。次に、利用収益還元についてですが、令和５年度の予算の事項別説明資料では３３１万円が還元されるということですが、実際に決算額にはどこにも出ていないのですけれども、どれぐらい収益が還元されたのでしょうか。","respondent":"若生健康課長","answer":"令和５年度の収益還元金につきましては、６１０万７,６６４円の還元となっています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、２０％ということに関しては、以前からお話ししていますが、区の努力についてはまた別の機会にお話しさせていただきたいと思います。それで、これは健康課にはならないかもしれないですけれども、決算書にも予算書にもモニタリングにも事務事業評価シートにも、今、６００万円という金額は入っていません。これについて金額を入れるべきだと思いますが、いかがでしょうか。","respondent":"若生健康課長","answer":"還元金につきましては、今後、載せ方については検討してまいりたいと考えております。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"というようなことを予算特別委員会で私が質問したら、当時の財政課長は「今後検討していきたいと思います」とおっしゃったのです。ということで半年たったのですけれども、どのような形で財政課は検討して、予算書・決算書等も含めてどのように入れていくのでしょうか。","respondent":"加島財政課長","answer":"今、決算書につきましては、歳入、諸収入の中の雑入、雑入の中の「等」に含まれているところです。今回、２度目のご意見を頂きまして大変恐縮ですけれども、予算書に向けて検討してまいりたいと考えております。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その金額が出ていると、この健康センターの指定管理の仕組みは、ほかの指定管理と違って、今のように区に６００万円という収益が上がるものですから、大変貴重な仕組みですので、その数字が分かるようにしていただきたいと思います。","respondent":"小林地域産業振興課長","answer":"平成２９年度から品川区とモンゴル３高専とのお付き合いというのが始まったわけですけれども、今年の５月に初めて区長にモンゴルに渡っていただきまして、今回、モンゴル３高専との間で連携協定、また教育・科学省および。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"モンゴルとの交流は前々からお話を伺っていますけれども、今言ったスタートアップ支援というところが、また１つさらに発展したことだと思いますので、ぜひ今後、拡大、そしてモンゴルと緊密な関係を取っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"私からは、３０３ページ、不妊治療助成事業、３２９ページ、商店街活性化事業費について伺います。よろしくお願いします。ただ、多分、当事者は結構多いと思うのですけれども、申請が少なかったところの理由をもう少し分析したほうがいいのかなと思うのですが、見解を伺います。お願いします。","respondent":"若生健康課長","answer":"こちらについてはまだ始まったばかりで、実績のほうがまだまだというところではありますけれども、徐々に増えてはきてございまして、今年度、急に今月、１０月になってから、数日で十数件というようなところで申請が上がってきたところもありますので。","id":"exchange-139"},{"speaker":"松本委員","kind":"提案","question":"これについては、もういろいろやっていただいているところで、特に私も区民の一人として大変感謝しているところで、これはもう質問というか、ご提案、ご要望というところですけれども、結構、私を含めて不妊治療をやっている人間というのは、多分、区内で探すというよりも、もう東京都内全域でクリニックを探して、実績が高いところに行くという構造があると思います。ぜひよろしくお願いします。","respondent":"小林地域産業振興課長","answer":"直近、令和５年度ということでいきますと、６０.３％ということで少し下がってありますけれども、この点、いろいろ政府の激変緩和措置というのがまた再開されるのではないか、あるいは、今後、ＬＥＤ化によって少し下がっていく部分。","id":"exchange-140"},{"speaker":"松本委員","kind":"質問・要望","question":"政府が延長するかどうかをまだ明確にしていないというのは、この１週間ぐらいでも出ていたので、そこも大きいのだろうと思います。それで、撤去費用というのは、あくまで商店会ということになると思うのですが、そのときに、ただ、そうはいっても、やはり大きなお金がかかるので、補助を使っても撤去するお金がないみたいな状況が生まれないのかというところが心配なのですが、その点はいかがでしょうか。","respondent":"小林地域産業振興課長","answer":"我々として、では残りの５分の１の部分はというところと、商店街の財務といいますか決算の状況というのは、適宜、区なり都に報告していただいているところでございまして、そのバランスを見ながら、商店街でもやはり解散しないように、我々としては。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問・要望","question":"最後、質問する時間が、私のほうが長かったので、できないのですけれども、ただ公共財という部分もあるので、撤去ではなくて、場合によっては区で財産として頂くということも検討していただきたいというところで、最後、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私は、３２７ページ、中小企業活性化事業費についてお聞きいたします。資金繰りはどうなのでしょうか。どのような課題があるのか。せんだって総務委員会でもありましたけれども、インボイス制度は皆さん、どう思われているのか。さらに店舗数や事業所数を、区内産業のことですから、品川区としてはしっかりと把握するべきだと私は思うのですが、その辺についてご見解をお聞かせください。","respondent":"小林地域産業振興課長","answer":"このデータについて、倒産件数も同じですけれども、コロナ前と同じような数字に戻ってきているところですので、我々としては引き続き、しっかり地域産業の支援予算を確保しつつ、助成措置なり、いろいろ支援措置というのをしっかり継続してまいりたいと考えております。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"今、私がお聞きしたのは、実体経済はどうなのですか。でも、これは区内産業の６００件ぐらいなのです。これだけを見て、今、課長は答弁されたのですけれども、我々は本当にこの品川区の実態、皆さん、小さな会社、店舗はどうなのか。それからサービス業はどうなのか。製造業はどうなのか。そういうふうに継承してきたかもしれないですが、私はもう変えるべきだと思いますけれども、いかがですか。","respondent":"小林地域産業振興課長","answer":"近隣区で見ましても、大田区や、大田区の場合は品川区よりも事業所数が４割多い程度ですけれども、やはり一定のサンプル数を見ながら、ただしそれを絶対視することなく、ほかのいろいろな景気指標あるいはその相談件数など。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"そのとき、分からないのですかというような問いもやはりかけられます。そういう方たちの実態に、やはり私は耳を傾けてほしい。一生懸命やられているのは分かるのですけれども、ここに、景況調査委託費、産業基礎調査などの経費と書かれていますけれども、これは何か調査をしているというふりなのですか。ここで、合理化設備への融資あっ旋ではなく、少しでも支援をしてやるべきではないですか。","respondent":"小林地域産業振興課長","answer":"今回は新紙幣の券売機対応なども進めてまいりますけれども、そういった現場の声というものにも対応した助成金も使っております。我々として、これだけという単独のメニューではなくて、できるだけ複数のメニューを事業者の皆さんに示させていただいて、商店街の予算もそうです。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"そうではないのではないですか。今、３,０００円でも５,０００円でも、光熱費を少しでも補填していただければありがたいと、みんな思うのではないですか。品川区で３億円を助成しているからには、このプレミアム付区内共通商品券が使われたお店または業種、お店の店舗数、使用された枚数などについては、きちんと私は議会に報告するべきではないかと思うのですが、この辺、ご見解をお聞かせください。","respondent":"小林地域産業振興課長","answer":"ただいまのプレミアム付区内共通商品券がどういう分野・業種で使われたかですけれども、令和５年度、これは春のデータですけれども、一番多く使われたのは生鮮食料品・加工食品・飲料等の分野、業種でいうと飲料品の小売業ということになりますけれども、これが３４％。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"我々は、その中で全く使われていない商品券、そういう店舗や、ごく僅かしか使われていない店舗もありますよね。私はそういう全体を、やはり区議会として、区議会議員として見てみたい。でも、それは全体ではないではないですか。区でやっているプレミアム付区内共通商品券は、意味がないではないですか。一部のところに助成しているようなものではないのですか。ご見解をお聞かせください。","respondent":"小林地域産業振興課長","answer":"対象店舗は約２,０００店舗と承知しております。その中で、先ほど申し上げたような業種別の対象ということで、区民の方に、あるいは区外の方も若干、１０％程度はいらっしゃいますけれども、９割近くは区民の方に使っていただいているものです。","id":"exchange-147"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２年前の予算特別委員会の質疑で、区民の生涯を通じた健康づくりを推進することを目的とした「健康プラン２１」に、リプロダクティブ・ヘルス／ライツを位置づけて具体化することを共産党は求めました。改めて「健康プラン」に、ジェンダー平等推進条例の視点でリプロダクティブ・ヘルス／ライツを明記して、性と生殖の健康と権利を保障する姿勢を明確にすべきと思いますけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"条例にそういった理念が加わったということは、私ども健康部門としても重要と考えておりまして、ただ、これについて、これまでの「健康プラン２１」の中にも、以前答弁したとおり、やはり概念というか、その言葉自体は入っていないものの。","id":"exchange-148"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ジェンダー平等推進条例ができて、９つの基本理念の中にリプロダクティブ・ヘルス／ライツが入りました。なので、リプロダクティブ・ヘルス／ライツは、子どもを産む・産まないを自分で決める権利を保障するものですので、安全な避妊や中絶を選択できることは大事な権利だと思いますけれども、それは当然、健康課でもそういう認識であるかどうかを確認させていただきたいと思います。","respondent":"若生健康課長","answer":"人工妊娠中絶等の、望まない妊娠というようなところの認識です。","id":"exchange-149"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"薬剤師との面談、そして薬の説明、プライバシーの保護などをしながら販売され、今年の１月３１日までで、全国では２,１８１件、東京都だけで２６６件の緊急避妊薬が販売されました。これもあまり知られていないことだと思います。こうした情報を区としても、リプロダクティブ・ヘルス／ライツの視点から区民に知らせていただきたいと思いますけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"緊急避妊薬についての、区としての周知ですが、緊急避妊薬は試験販売という形で、今、開始されているところで、これについては本格実施がまだというところでもありますので、区としては状況を注視しているところではあります。","id":"exchange-150"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"権利なので、ぜひそれを広げていただきたいのですけれども、心も体も守ることができる方法があるという情報を、とにかく知らな過ぎる、少な過ぎるという状況なのです。なので、健康課からもさらに発信していただきたいですし、女性の身体を守る、そして産む・産まないも自分で決定できる、そういう権利だということを積極的に健康課としても発信していただきたいということを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"あくつ委員","kind":"質問・要望","question":"時間があれば３１３ページ、環境保全事業、宅配ポスト設置支援事業について伺っていきます。産後ケア事業についてですけれども、午前中、ひがし委員からも質問があったのですが、私からも具体的な確認をさせていただきたいと思います。令和５年度と比較して、令和６年度は事業が拡充されたということですが、拡充された内容について簡潔に教えてください。","respondent":"石橋品川保健センター所長","answer":"令和６年度に拡充した内容になります。日帰り型につきましては、指定医療機関が３施設、増えました。自己負担額も軽減しています。訪問型・宿泊型につきましては合わせて５回までの利用、１歳未満までの月齢に延長をさせていただいたところになります。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"質問・要望","question":"以下、品川区産後ケア事業をご利用された方からのご相談を基に質問します。一方で、例えば大田区の場合、最大で５泊６日の利用が可能です。体調等に合わせて分割利用、ラグジュアリーなところを利用するということもそうなのですけれども、全部を丸々利用しなくても、１回休んで、また自宅に戻って、そしてまた利用できるという分割利用も可能にしていただきたいと思いますが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"泊数の違いがあることも認識しております。今後、病院の病床等の確保の面もいろいろありますので、その辺りも含めまして、泊数は、利用者の声も基に、いろいろ検討はしていきたいと考えております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"質問","question":"自己負担額です。品川区では、指定医療機関であれば、どの病院であっても現在１泊２日、先ほど拡充されまして７,５００円で済むと。２泊３日では１万５,０００円。そして、３泊４日、最大で２万２,５００円で済むというふうになっています。これ以上安くしろというのは、なかなか難しいと思うのですけれども、自己負担額の設定を、同等のものをお願いしたいと思いますが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"ただ、先ほどもお話しさせていただいたとおり、近隣区の状況もこちらで把握しております。７医療機関で、それぞれ今、区の負担額が医療機関ごとに違う部分もありますので、今後、自己負担額を一律にするかどうかも含めまして、検討していきたいと考えております。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問","question":"どうぞよろしくお願いします。最後に、先ほど、ひがし委員からもありましたけれども、申請方法について伺います。品川区では事前申請が必要となっています。こうした手続についても、紙の承認通知書の発行などに伴う事前申請の有無は、医療機関によっても受入れ方が異なるのかもしれないですけれども、妊婦が一番利用しやすい形にしていただければと思うのですけれども、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"利用申請書を今、医療機関に持っていくということが必須になっておりますので、その辺りは、各医療機関とどのような形で手続を進めていけるかということも今後しっかり検討してまいりたいと考えております。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回の監査意見書の９１ページに、次のような審査の総括意見があります。このような指摘がありました。所管である地域産業振興課では、この決算審査意見書の総括意見というのはご覧になりましたでしょうか。そして、この監査意見の指摘する新たな課題については、区の関係部署の協力体制、組織横断的な問題解決ということを求めているのですけれども、具体的にはどのようにお考えになりますでしょうか。","respondent":"小林地域産業振興課長","answer":"これについては、我々、商店街支援の部署だけでなく、商店街連合会のスタッフ、あるいはサポーターの皆さんというところも含めて、例えば財務状況がどうなっているか、今後の活動の見通しはどうであるかということ等を含めて、もし仮に今後。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問","question":"今回もそこまで行き着くのに結構いろいろな紆余曲折があったという感じがします。１点だけ、先ほど松本委員の最後の質問、意見というかがありましたけれども、商店街の街路灯の譲渡、維持管理について、品川区として、これは場合としては受けていただけるのかどうか。ここについてどのようにお考えか、最後にお聞かせください。","respondent":"小林地域産業振興課長","answer":"監査の意見書にもあるとおり、基本的には商店街の私有物という扱いです。ただ、いろいろ、この問題は、今現状は問題がないところですけれども、今後、そういう対処が、基本原則論だけで対処できない場合がないのかというところは考えてまいりたいと考えています。","id":"exchange-157"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、３２７ページの中小企業活性化事業費のうち、経営相談事業についてお聞きします。時間があれば、２９７ページのＡＥＤ管理費です。経営相談事業についてお聞きします。","respondent":"小林地域産業振興課長","answer":"２番目が開業。こちらは徐々に増えてきている相談ですけれども、７８４件。３番目としまして、経営の事業計画の見直しといったものにつきまして、これが８８件程度と認識しています。","id":"exchange-158"},{"speaker":"まつざわ委員","kind":"確認","question":"１年間で３,６４１件。これは多分、１社で複数の相談もあるかと思っています。１番が要は金融、２番目が開業で、３番目が見直しということは確認が取れました。さらにお伺いしたいのですけれども、午前中にも質疑があって、インボイスの話が今回、多く出ました。このインボイスというのも、昨年の１０月から導入されています。これをまず聞かせてください。そして、あれば件数なども教えてください。","respondent":"小林地域産業振興課長","answer":"ただいまご質問のありました経営相談の実績３,６４１件の中ですけれども、直接的にといいますか、そのものずばり、インボイスの相談というものについては、直接の相談件数は０件であると認識しておりまして、これは品川区だけのことかと思い。","id":"exchange-159"},{"speaker":"まつざわ委員","kind":"質問","question":"相談が０件、近隣も少ないのですか。そうすると、経営相談をされている方が３,６４１件です。これだけいらっしゃっていて、インボイス制度の対応に困っていると陳情にもありました。そういう人は一体どこに相談されているのか教えてください。","respondent":"小林地域産業振興課長","answer":"少し古い数字になりますけれども、令和５年度の上半期には１か月当たり４万件から６万件の相談対応というのが国で行われていたという新聞報道を確認しております。","id":"exchange-160"},{"speaker":"まつざわ委員","kind":"質問","question":"事業者の皆さんの、こういうインボイスの相談というのが、品川区、近隣で言うと大田区という自治体ではなくて、国の今、先ほど相談窓口というのはインボイスコールセンターに集中して寄せられている理由はどういったものなのか、分析があったら教えてください。","respondent":"小林地域産業振興課長","answer":"ただ一般的な相談ということにとどまらず、例えばこれは、きめの細かい対応としまして、文化芸術産業、いわゆるクリエイターの方などの相談には文部科学省が、あるいは建設業の相談には国土交通省が。","id":"exchange-161"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"一方で品川区の話に戻らせてもらいますと、区にも３,６４１件、経営相談が寄せられているというお話でした。地域経済に関するお困り事としまして、区内事業者の皆さんは、長期化する物価高騰、そして人手不足、デジタル化など、様々な経営課題の対応を求めていく必要があると思います。これは、事務事業評価シートを見ましても、しっかりと目標の数字というのはクリアしていることが確認できました。","respondent":"若生健康課長","answer":"昨年度のＡＥＤの使用実績ですが、内訳としては、高齢者施設で７回、しながわ中央公園で１回、家庭あんしんセンターで１回、それから学校で２回となっております。","id":"exchange-162"},{"speaker":"まつざわ委員","kind":"質問","question":"こういうケースというのは、やはりあります。でもこれは、ＡＥＤの場所が分からないと大変困ると思っているのですけれども、ＡＥＤの場所が分かる対応というのが今、品川区はあるのか教えてください。","respondent":"若生健康課長","answer":"こちらは全国的にも広く活用されておりまして、区設置以外の民間施設も含めた、国内で３０万件以上のＡＥＤ登録があるということで、こちらを積極的に、活用を促しています。","id":"exchange-163"},{"speaker":"まつざわ委員","kind":"意見","question":"マップは存じています。しかしこれは、探すときにマップを見るのが大変で、例えばアプリで場所がありますよというのも、実際に最近、新しくなっております。これは、ＡＥＤが解禁されて今年で２０年目になりますので、ＡＥＤの設置場所が誰でも分かるようにしていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-164"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6855#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":116348,"voices":350}},{"id":"r06-20241009-10","meetingId":"r06-cm10","date":"2024年10月9日","dateIso":"2024-10-09","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"まつざわ委員長","kind":"確認","question":"ないようですので、私から１件ご報告いたします。９月１８日の議会運営委員会で確認しましたウェルビーイング・ＳＤＧｓ推進事業実行委員会監事の推薦についてです。以上でその他を終了いたします。以上で本日の予定は全て終了いたしました。次回の開催は、明日１０月１０日木曜日、本会議休憩中の開催を予定しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/116834?Template=document&Id=6839#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2631,"voices":18}}]);
